fn video_tab(ctx: &mut Ctx, y0: i32) {
    let lang = ctx.lang;
    let v = &ctx.state.settings.video;

    // Two 312px columns centered on the viewport (16px gutter) keep every
    // control reachable at the smallest logical width: the left column
    // holds the classic video controls, the right column the lighting &
    // shadow-gameplay toggles. Both clip symmetrically on narrow screens
    // and can never overlap because the gutter is constant.
    let cx = ctx.w / 2;
    let lx = cx - 320;
    let rx = cx + 8;
    let bw = 312;
    let step = if ctx.h < 300 { 22 } else { 24 };
    let vy = |i: i32| y0 + i * step;
    let pair = |ctx: &mut Ctx,
                i: i32,
                col: i32,
                id: WidgetId,
                key: SettingKey,
                label: &str| {
        let bx = lx + col * 160;
        ctx.btn(id, lr(bx, vy(i), 150, 20), label);
        ctx.dirty_dot(key, bx + 154, vy(i) + 6);
    };

    let (x, y) = (lx, vy(0));
    ctx.btn(
        WidgetId::VideoPreset,
        lr(x, y, bw, 20),
        &format!(
            "{}: {}",
            tr(lang, "Preset", "プリセット"),
            v.preset.label(lang)
        ),
    );
    ctx.dirty_dot(SettingKey::VideoPreset, x + bw + 6, y + 6);

    let (x, y) = (lx, vy(1));
    let frac = v.view_distance.saturating_sub(6) as f32 / 26.0;
    ctx.slider(
        WidgetId::VideoViewDistance,
        lr(x, y, bw, 20),
        frac,
        &format!(
            "{}: {} {}",
            tr(lang, "View Distance", "描画距離"),
            v.view_distance,
            tr(lang, "chunks", "チャンク")
        ),
    );
    ctx.dirty_dot(SettingKey::VideoViewDistance, x + bw + 6, y + 6);

    pair(
        ctx,
        2,
        0,
        WidgetId::VideoFullscreen,
        SettingKey::DisplayFullscreen,
        &format!(
            "{}: {}",
            tr(lang, "Fullscreen", "フルスクリーン"),
            onoff(ctx.state.settings.fullscreen)
        ),
    );
    let scale = if ctx.state.settings.gui_scale == 0 {
        tr(lang, "Auto", "自動").to_string()
    } else {
        ctx.state.settings.gui_scale.to_string()
    };
    pair(
        ctx,
        2,
        1,
        WidgetId::VideoGuiScale,
        SettingKey::DisplayGuiScale,
        &format!("{}: {scale}", tr(lang, "GUI Scale", "GUIサイズ")),
    );

    pair(
        ctx,
        3,
        0,
        WidgetId::VideoGamma,
        SettingKey::DisplayGamma,
        &format!(
            "{}: {}%",
            tr(lang, "Brightness", "明るさ"),
            ctx.state.settings.gamma_pct
        ),
    );
    pair(
        ctx,
        3,
        1,
        WidgetId::VideoClouds,
        SettingKey::VideoClouds,
        &format!(
            "{}: {}",
            tr(lang, "Clouds", "雲"),
            v.clouds.label(lang)
        ),
    );

    pair(
        ctx,
        4,
        0,
        WidgetId::VideoLod,
        SettingKey::VideoLod,
        &format!("{}: {}", tr(lang, "LOD", "遠景LOD"), v.lod.label(lang)),
    );
    pair(
        ctx,
        4,
        1,
        WidgetId::VideoGpuBackend,
        SettingKey::VideoGpuBackend,
        &format!("{}: {}", tr(lang, "GPU", "GPU"), v.gpu_backend.label(lang)),
    );

    pair(
        ctx,
        5,
        0,
        WidgetId::VideoVsync,
        SettingKey::VideoVsync,
        &format!("VSync: {}", onoff(v.vsync)),
    );
    pair(
        ctx,
        5,
        1,
        WidgetId::VideoSmoothLighting,
        SettingKey::VideoSmoothLighting,
        &format!(
            "{}: {}",
            tr(lang, "Smooth Light", "スムースライト"),
            onoff(v.smooth_lighting)
        ),
    );

    // FPS cap: slider + custom numeric field on the same row (no overlap).
    let (x, y) = (lx, vy(6));
    let frac = v.fps_step_index() as f32 / (FPS_CAP_STEPS.len() - 1) as f32;
    ctx.slider(
        WidgetId::VideoFpsSlider,
        lr(x, y, 200, 20),
        frac,
        &format!(
            "{}: {}",
            tr(lang, "FPS Cap", "FPS上限"),
            v.fps_cap_label(lang)
        ),
    );
    ctx.textfield(
        WidgetId::VideoFpsField,
        lr(x + 208, y, 100, 20),
        ctx.state.fps_field_text(),
        ctx.state.fps_field_active(),
        tr(lang, "custom fps", "カスタムfps"),
    );
    ctx.dirty_dot(SettingKey::VideoFpsCap, x + bw + 6, y + 6);
    if ctx.state.fps_field_error() {
        ctx.text(
            x + 208,
            y + 22,
            1,
            pal::DANGER,
            tr(lang, "use 0 or 10-2000", "0 または 10-2000"),
        );
    }

    let (x, y) = (lx, vy(7));
    let bg_label = if v.background_fps == 0 {
        tr(lang, "Off", "オフ").to_string()
    } else {
        format!("{} fps", v.background_fps)
    };
    ctx.btn(
        WidgetId::VideoBackgroundFps,
        lr(x, y, bw, 20),
        &format!(
            "{}: {}",
            tr(lang, "Background FPS", "バックグラウンドFPS"),
            bg_label
        ),
    );
    ctx.dirty_dot(SettingKey::VideoBackgroundFps, x + bw + 6, y + 6);

    // Host-RAM cache budget: free 512-MiB slider steps from Auto (0) up
    // to the detected host total — no artificial ceiling. The runtime's
    // live OOM guard trims distant caches early when the OS runs low, so
    // even a maxed-out cap can never get the process killed.
    let (x, y) = (lx, vy(8));
    ctx.slider(
        WidgetId::VideoRamBudget,
        lr(x, y, bw, 20),
        v.ram_budget_frac(),
        &format!(
            "{}: {}",
            tr(lang, "Host RAM Budget", "ホストRAM上限"),
            v.ram_budget_label(lang)
        ),
    );
    ctx.dirty_dot(SettingKey::VideoRamBudget, x + bw + 6, y + 6);

    // --- Lighting & world-scoped toggles (right column) ----------------
    let lighting: [(WidgetId, SettingKey, &str, &str, bool); 5] = [
        (
            WidgetId::VideoEntityShadows,
            SettingKey::VideoEntityShadows,
            "Shadows",
            "影",
            v.entity_shadows,
        ),
        (
            WidgetId::VideoComfortExposure,
            SettingKey::VideoComfortExposure,
            "Eye-Comfort Exposure",
            "まぶしさを抑制",
            v.comfort_exposure,
        ),
        (
            WidgetId::VideoDynamicLights,
            SettingKey::VideoDynamicLights,
            "Dynamic Lights",
            "動くライト",
            v.dynamic_lights,
        ),
        (
            WidgetId::VideoEnchantmentGlint,
            SettingKey::VideoEnchantmentGlint,
            "Enchantment Glint",
            "エンチャントきらめき",
            v.enchantment_glint,
        ),
        (
            WidgetId::VideoIndirectLightBounce,
            SettingKey::VideoIndirectLightBounce,
            "Indirect Light Bounce",
            "間接バウンスライト",
            v.indirect_light_bounce,
        ),
    ];
    ctx.text(rx, vy(0), 1, pal::ACCENT, tr(lang, "LIGHTING", "ライティング"));
    for (i, (id, key, en, ja, on)) in lighting.iter().enumerate() {
        let (x, y) = (rx, vy(i as i32 + 1));
        ctx.btn(
            *id,
            lr(x, y, bw, 20),
            &format!("{}: {}", tr(lang, en, ja), onoff(*on)),
        );
        ctx.dirty_dot(*key, x + bw + 6, y + 6);
    }
    ctx.text(
        rx,
        vy(6),
        1,
        pal::ACCENT,
        tr(lang, "WORLD (LOCAL)", "ワールド（ローカル）"),
    );
    let world: [(WidgetId, SettingKey, &str, &str, bool); 2] = [
        (
            WidgetId::VideoDirectionalShadowGameplay,
            SettingKey::VideoDirectionalShadowGameplay,
            "Shadow Light Gameplay",
            "シャドウゲームプレイ",
            v.directional_shadow_gameplay,
        ),
        (
            WidgetId::VideoLazyCatchupGameplay,
            SettingKey::VideoLazyCatchupGameplay,
            "Unloaded Catch-Up",
            "追いつき処理",
            v.lazy_catchup_gameplay,
        ),
    ];
    for (i, (id, key, en, ja, on)) in world.iter().enumerate() {
        let (x, y) = (rx, vy(i as i32 + 7));
        ctx.btn(
            *id,
            lr(x, y, bw, 20),
            &format!("{}: {}", tr(lang, en, ja), onoff(*on)),
        );
        ctx.dirty_dot(*key, x + bw + 6, y + 6);
    }
    // Scope hint for the opt-in gameplay toggles: local/hosted worlds
    // only — remote servers keep their own host settings.
    ctx.text(
        rx,
        vy(9) + 2,
        1,
        pal::TEXT_DIM,
        tr(
            lang,
            "Local & hosted worlds only",
            "ローカル・フレンドワールドのみ",
        ),
    );
}

/// Human-friendly display name for a raw `winit` key/button name stored
/// in `settings.keys`: `"KeyW"` → `"W"`, `"Digit3"` → `"3"`,
/// `"ShiftLeft"` → `"L-Shift"`/`"左Shift"`, `"Slash"` → `"/"`,
/// `"Escape"` → `"Esc"`, `"Numpad4"` → `"Num4"`, … Unknown names pass
/// through unchanged so the Controls tab never shows raw SDL enums.
pub fn format_key_label(raw: &str, lang: UiLang) -> String {
    if let Some(rest) = raw.strip_prefix("Key") {
        if rest.len() == 1 && rest.chars().next().is_some_and(|c| c.is_ascii_uppercase()) {
            return rest.to_string();
        }
    }
    if let Some(rest) = raw.strip_prefix("Digit") {
        if rest.len() == 1 && rest.chars().next().is_some_and(|c| c.is_ascii_digit()) {
            return rest.to_string();
        }
    }
    if let Some(rest) = raw.strip_prefix("Numpad") {
        if !rest.is_empty() {
            return format!("Num{rest}");
        }
    }
    match raw {
        "Space" => tr(lang, "Space", "スペース").to_string(),
        "ShiftLeft" => tr(lang, "L-Shift", "左Shift").to_string(),
        "ShiftRight" => tr(lang, "R-Shift", "右Shift").to_string(),
        "ControlLeft" => tr(lang, "L-Ctrl", "左Ctrl").to_string(),
        "ControlRight" => tr(lang, "R-Ctrl", "右Ctrl").to_string(),
        "AltLeft" => tr(lang, "L-Alt", "左Alt").to_string(),
        "AltRight" => tr(lang, "R-Alt", "右Alt").to_string(),
        "SuperLeft" => tr(lang, "L-Super", "左Super").to_string(),
        "SuperRight" => tr(lang, "R-Super", "右Super").to_string(),
        "Escape" => "Esc".to_string(),
        "Backspace" => "BS".to_string(),
        "Enter" | "Return" | "NumpadEnter" => "Enter".to_string(),
        "CapsLock" => "Caps".to_string(),
        "ArrowUp" => tr(lang, "Up", "上").to_string(),
        "ArrowDown" => tr(lang, "Down", "下").to_string(),
        "ArrowLeft" => tr(lang, "Left", "左").to_string(),
        "ArrowRight" => tr(lang, "Right", "右").to_string(),
        "PageUp" => "PgUp".to_string(),
        "PageDown" => "PgDn".to_string(),
        "Insert" => "Ins".to_string(),
        "Delete" => "Del".to_string(),
        "Slash" => "/".to_string(),
        "Backslash" => "\\".to_string(),
        "Minus" => "-".to_string(),
        "Equal" => "=".to_string(),
        "Comma" => ",".to_string(),
        "Period" => ".".to_string(),
        "Semicolon" => ";".to_string(),
        "Apostrophe" => "'".to_string(),
        "Grave" | "Backquote" => "`".to_string(),
        "BracketLeft" => "[".to_string(),
        "BracketRight" => "]".to_string(),
        "MouseLeft" | "Mouse1" => "LMB".to_string(),
        "MouseRight" | "Mouse2" => "RMB".to_string(),
        "MouseMiddle" | "Mouse3" => "MMB".to_string(),
        _ => raw.to_string(),
    }
}

fn controls_tab(ctx: &mut Ctx, y0: i32) {
    let lang = ctx.lang;
    const LABELS: [(&str, &str); 17] = [
        ("Forward", "前進"),
        ("Back", "後退"),
        ("Left", "左"),
        ("Right", "右"),
        ("Jump", "ジャンプ"),
        ("Sneak", "スニーク"),
        ("Sprint", "ダッシュ"),
        ("Inventory", "インベントリ"),
        ("Drop", "ドロップ"),
        ("Swap Offhand", "オフハンド"),
        ("Chat", "チャット"),
        ("Command", "コマンド"),
        ("Zoom", "ズーム"),
        ("Perspective", "カメラ切替"),
        ("Fullscreen", "フルスクリーン"),
        ("Advancements", "進捗"),
        ("Item Sort", "アイテム整理"),
    ];
    let panel_x = (ctx.w - 348).max(4) / 2;
    for (index, (en, ja)) in LABELS.iter().enumerate() {
        let column = (index / 9) as i32;
        let row_index = (index % 9) as i32;
        let x = panel_x + column * 174;
        let y = y0 + row_index * 22;
        ctx.text(
            x,
            y + 4,
            1,
            pal::TEXT,
            crate::draw::first_px(tr(lang, en, ja), 96),
        );
        let binding = if ctx.state.capturing_key_binding == Some(index) {
            tr(lang, "Press…", "キーを押す").to_string()
        } else {
            format_key_label(ctx.state.settings.keys.get(index).unwrap_or("-"), lang)
        };
        ctx.btn(WidgetId::ControlKey(index), lr(x + 96, y, 74, 18), &binding);
    }

    let y = y0 + 9 * 22;
    let left = panel_x;
    ctx.btn(
        WidgetId::VideoInvertY,
        lr(left, y, 168, 18),
        &format!(
            "{}: {}",
            tr(lang, "Invert Y", "Y軸反転"),
            onoff(ctx.state.settings.mouse_invert_y)
        ),
    );
    ctx.dirty_dot(SettingKey::DisplayInvertY, left + 174, y + 5);
    if ctx.state.capturing_key_binding.is_some() {
        ctx.text(
            left,
            y + 26,
            1,
            pal::ACCENT,
            tr(
                lang,
                "Press any key…  Esc cancels",
                "キーを押してください… (Escでキャンセル)",
            ),
        );
    }
}

fn audio_tab(ctx: &mut Ctx, y0: i32) {
    let lang = ctx.lang;
    let a = &ctx.state.settings.audio;

    let rows: [(WidgetId, SettingKey, &str, u8); 7] = [
        (
            WidgetId::AudioMaster,
            SettingKey::AudioMaster,
            tr(lang, "Master Volume", "マスター音量"),
            a.master,
        ),
        (
            WidgetId::AudioMusic,
            SettingKey::AudioMusic,
            tr(lang, "Music", "BGM"),
            a.music,
        ),
        (
            WidgetId::AudioBlocks,
            SettingKey::AudioBlocks,
            tr(lang, "Blocks", "ブロック"),
            a.blocks,
        ),
        (
            WidgetId::AudioHostile,
            SettingKey::AudioHostile,
            tr(lang, "Hostile Mobs", "敵モブ"),
            a.hostile,
        ),
        (
            WidgetId::AudioFriendly,
            SettingKey::AudioFriendly,
            tr(lang, "Friendly Mobs", "友好モブ"),
            a.friendly,
        ),
        (
            WidgetId::AudioMaxVolumeCap,
            SettingKey::AudioMaxVolumeCap,
            tr(lang, "Loud Sound Limiter", "音量ガード"),
            a.max_volume_cap,
        ),
        (
            WidgetId::AudioMaxConcurrent,
            SettingKey::AudioMaxConcurrentSameSound,
            tr(lang, "Same-Sound Limit", "重複音の制限"),
            a.max_concurrent_same_sound,
        ),
    ];
    for (i, (id, key, name, val)) in rows.iter().enumerate() {
        let (x, y) = row(ctx, i as i32, y0);
        let frac = if *id == WidgetId::AudioMaxConcurrent {
            (*val as f32 - 1.0) / 31.0
        } else {
            *val as f32 / 100.0
        };
        let label = if *id == WidgetId::AudioMaxConcurrent {
            format!("{name}: {val}/tick")
        } else if *id == WidgetId::AudioMaxVolumeCap {
            // Intuitive dB readout (OFF/Muted/Gentle/Medium/Strong)
            // instead of a bare percent.
            format!("{name}: {}", a.max_volume_cap_label(lang))
        } else {
            format!("{name}: {val}%")
        };
        ctx.slider(*id, lr(x, y, 320, 20), frac, &label);
        ctx.dirty_dot(*key, x + 326, y + 6);
    }

    // 3D Audio: a plain OFF/ON toggle — full 64-ray quality internally,
    // no ray-count dropdown to mis-set.
    let (x, y) = row(ctx, 7, y0);
    ctx.btn(
        WidgetId::AudioSpatial3d,
        lr(x, y, 320, 20),
        &format!(
            "{}: {}",
            tr(lang, "3D Audio", "立体音響"),
            onoff(ctx.state.settings.visual.spatial_audio_3d)
        ),
    );
    ctx.dirty_dot(SettingKey::AudioSpatial3d, x + 326, y + 6);

    ctx.ctext(
        ctx.w / 2,
        y0 + 8 * 24 + 2,
        1,
        pal::TEXT_DIM,
        tr(
            lang,
            "Limiter caps spike loudness; coalescing thins stacked sounds",
            "リミッターは音量スパイクを抑制し、重複音を間引きます",
        ),
    );
}

fn qol_tab(ctx: &mut Ctx, y0: i32) {
    let lang = ctx.lang;
    let q = &ctx.state.settings.qol;
    // Below 400 logical px the tab tightens to an 18px/16px rhythm so
    // every toggle plus the MiniHUD chip grid clears Done/About at the
    // standard 360px-tall window; larger screens keep the standard
    // 24px/20px grid.
    let compact = ctx.h < 400;
    let (step, bh) = if compact { (18, 16) } else { (24, 20) };
    let x = ctx.w / 2 - 160;
    let y0 = if compact { y0 - 2 } else { y0 };
    let qy = |i: i32| y0 + i * step;

    ctx.slider(
        WidgetId::QolToolWarn,
        lr(x, qy(0), 320, bh),
        q.tool_warn_percent as f32 / 100.0,
        &format!(
            "{}: {}%",
            tr(lang, "Low-Durability Warning", "耐久低下の警告"),
            q.tool_warn_percent
        ),
    );
    ctx.dirty_dot(SettingKey::QolToolWarnPercent, x + 326, qy(0) + (bh - 8) / 2);

    let frac = (q.chat_history_lines as f32 - 100.0) / 4900.0;
    ctx.slider(
        WidgetId::QolChatHistory,
        lr(x, qy(1), 320, bh),
        frac,
        &format!(
            "{}: {} {}",
            tr(lang, "Chat History", "チャット履歴"),
            q.chat_history_lines,
            tr(lang, "lines", "行")
        ),
    );
    ctx.dirty_dot(SettingKey::QolChatHistoryLines, x + 326, qy(1) + (bh - 8) / 2);

    // Boolean toggles share compact two-per-row cells — the same
    // 156px pairing the MiniHUD/Subtitles row already uses — so every
    // setting stays reachable at the smallest sane window. Labels that
    // need the full width (Support Links, Crash mode) keep their own
    // row.
    let pair = |ctx: &mut Ctx,
                i: i32,
                col: i32,
                id: WidgetId,
                key: SettingKey,
                label: &str| {
        let bx = x + col * 164;
        ctx.btn(id, lr(bx, qy(i), 156, bh), label);
        ctx.dirty_dot(key, bx + 162, qy(i) + (bh - 8) / 2);
    };

    pair(
        ctx,
        2,
        0,
        WidgetId::QolSmoothZoom,
        SettingKey::QolSmoothZoom,
        &format!(
            "{}: {}",
            tr(lang, "Smooth Zoom", "ズーム"),
            onoff(q.smooth_zoom)
        ),
    );
    pair(
        ctx,
        2,
        1,
        WidgetId::QolPreventBreak,
        SettingKey::QolPreventToolBreak,
        &format!(
            "{}: {}",
            tr(lang, "Break Guard", "破壊ガード"),
            onoff(q.prevent_tool_break)
        ),
    );

    let minihud_label = match q.mini_hud_preset() {
        MiniHudPreset::Off => "OFF",
        MiniHudPreset::Basic => tr(lang, "Basic", "基本"),
        MiniHudPreset::Advanced => tr(lang, "Advanced", "詳細"),
    };
    pair(
        ctx,
        3,
        0,
        WidgetId::QolMiniHud,
        SettingKey::QolMiniHud,
        &format!("MiniHUD: {minihud_label}"),
    );
    pair(
        ctx,
        3,
        1,
        WidgetId::QolSubtitles,
        SettingKey::QolShowSubtitles,
        &format!(
            "{}: {}",
            tr(lang, "Subtitles", "字幕"),
            onoff(q.show_subtitles)
        ),
    );

    pair(
        ctx,
        4,
        0,
        WidgetId::QolRetainChat,
        SettingKey::QolRetainChatOnReconnect,
        &format!(
            "{}: {}",
            tr(lang, "Keep Chat", "履歴保持"),
            onoff(q.retain_chat_on_reconnect)
        ),
    );
    pair(
        ctx,
        4,
        1,
        WidgetId::QolToasts,
        SettingKey::QolToastNotifications,
        &format!(
            "{}: {}",
            tr(lang, "Toasts", "トースト"),
            onoff(q.toast_notifications)
        ),
    );

    // Engine-quality essentials only. The mod-overlapping helpers
    // (auto-replenish, quick-stack, food/saturation preview, shulker
    // peek) deliberately have no toggle here — `QolSettings` keeps the
    // fields default-false for settings-file compatibility, and the
    // footer points players at Mods > Recommended for the dedicated
    // community mods that do those jobs better.
    pair(
        ctx,
        5,
        0,
        WidgetId::QolAutoReconnect,
        SettingKey::QolAutoReconnect,
        &format!(
            "{}: {}",
            tr(lang, "Reconnect", "再接続"),
            onoff(q.auto_reconnect)
        ),
    );
    pair(
        ctx,
        5,
        1,
        WidgetId::QolChatScrollLock,
        SettingKey::QolChatScrollLock,
        &format!(
            "{}: {}",
            tr(lang, "Scroll Lock", "スクロール保持"),
            onoff(q.chat_scroll_lock)
        ),
    );

    ctx.btn(
        WidgetId::QolCrashMode,
        lr(x, qy(6), 320, bh),
        &format!(
            "{}: {}",
            tr(lang, "Crash Report Mode", "クラッシュレポート"),
            q.crash_report_mode.label(lang)
        ),
    );
    ctx.dirty_dot(SettingKey::QolCrashReportMode, x + 326, qy(6) + (bh - 8) / 2);

    pair(
        ctx,
        7,
        0,
        WidgetId::QolShowSupportLinks,
        SettingKey::QolShowSupportLinks,
        &format!(
            "{}: {}",
            tr(lang, "Support Links", "支援リンク"),
            onoff(q.show_support_links)
        ),
    );
    // `Ctrl+O` flips the same setting in-game.
    pair(
        ctx,
        7,
        1,
        WidgetId::QolRecipeOverlay,
        SettingKey::QolRecipeOverlay,
        &format!(
            "{}: {}",
            tr(lang, "Recipe Search", "レシピ検索UI"),
            onoff(q.recipe_overlay_enabled)
        ),
    );

    // -- Built-in helper toggles (relocated from the Controls tab) ----
    pair(
        ctx,
        8,
        0,
        WidgetId::QolBuiltin(0),
        SettingKey::QolLookingAtHud,
        &format!(
            "{}: {}",
            tr(lang, "Look-at HUD", "注視HUD"),
            onoff(ctx.state.settings.qol_looking_at_hud)
        ),
    );
    pair(
        ctx,
        8,
        1,
        WidgetId::QolBuiltin(1),
        SettingKey::QolMouseTweaks,
        &format!(
            "{}: {}",
            tr(lang, "Mouse Tweaks", "マウス操作補助"),
            onoff(ctx.state.settings.qol_mouse_tweaks)
        ),
    );
    pair(
        ctx,
        9,
        0,
        WidgetId::QolBuiltin(2),
        SettingKey::QolInventorySort,
        &format!(
            "{}: {}",
            tr(lang, "Item Sort", "アイテム整理"),
            onoff(ctx.state.settings.qol_inventory_sort)
        ),
    );
    pair(
        ctx,
        9,
        1,
        WidgetId::QolBuiltin(3),
        SettingKey::ZshCommandBar,
        &format!(
            "{}: {}",
            tr(lang, "Cmd Hints", "コマンド補完"),
            onoff(ctx.state.settings.zsh_command_bar)
        ),
    );

    // MiniHUD segment chips: only meaningful while MiniHUD itself is
    // on — hidden (not greyed) when the preset is Off. Keybind conflicts
    // are surfaced on the dedicated Controls tab now, so nothing else
    // renders below this grid.
    let mini = &q.mini_hud;
    let last_row = if mini.enabled { 12 } else { 9 };
    if mini.enabled {
        let segments = [
            ("FPS", mini.show_fps),
            ("Coords", mini.show_coords),
            ("Biome", mini.show_biome),
            ("Facing", mini.show_facing),
            ("Ping", mini.show_ping),
            ("TPS", mini.show_mspt_tps),
            ("Light", mini.show_light_level),
            ("Chunks", mini.show_chunks_entities),
            ("Memory", mini.show_ram),
        ];
        for (index, (label, enabled)) in segments.iter().enumerate() {
            let column = (index % 3) as i32;
            let row_index = (index / 3) as i32;
            ctx.btn(
                WidgetId::MiniHudSegment(index),
                lr(x + column * 108, qy(10 + row_index), 104, bh),
                &format!("{label}: {}", onoff(*enabled)),
            );
        }
    }

    // Subtle footer — only when the last content row leaves it clear.
    // Both lines sit INSIDE the settings card: its bottom border is 6px
    // above `band_top` (`panel(…, h - 92)` vs `band_top = h - 32`), so
    // anchoring the last line 24px up keeps ~10px of padding between
    // the text and the border instead of painting across it.
    if qy(last_row) + bh + 4 <= ctx.band_top - 36 {
        // Subtle footer: point players at the community catalog instead
        // of stacking more built-in duplicates of respected mods.
        ctx.ctext(
            ctx.w / 2,
            ctx.band_top - 36,
            1,
            pal::TEXT_DIM,
            tr(
                lang,
                "Optional HUD/inventory mods: Mods > Recommended",
                "追加のHUDやインベントリModは Mods > Recommended へ",
            ),
        );
        ctx.ctext(
            ctx.w / 2,
            ctx.band_top - 24,
            1,
            pal::TEXT_DIM,
            tr(
                lang,
                "Crash reports only - zero gameplay telemetry",
                "クラッシュレポートのみ — ゲームプレイのテレメトリなし",
            ),
        );
    }
}

