// ---------------------------------------------------------------------------
// Friends
// ---------------------------------------------------------------------------

/// `megu-id:` strings are 66 chars — far wider than any row. Show a
/// middle-elided form (`megu-id:ABCDEFGH..WXYZ`); the full string is
/// only ever copied, never retyped.
fn friend_id_short(id: &str) -> String {
    let chars: Vec<char> = id.chars().collect();
    if chars.len() <= 24 {
        return id.to_string();
    }
    let head: String = chars[..18].iter().collect();
    let tail: String = chars[chars.len() - 4..].iter().collect();
    format!("{head}..{tail}")
}

/// One friends-allowlist row: name + truncated id (row-select region),
/// SAS/online column, Selected checkbox, instant Remove. Narrow rows
/// shed the optional columns before shedding Remove.
fn friend_row(ctx: &mut Ctx, x0: i32, y: i32, rw: i32, i: usize) {
    let entry = &ctx.state.friends.friends[i];
    let selected = ctx.state.friends.selected == Some(i);
    let show_sas = rw >= 240;
    let show_cb = rw >= 160;
    let right_w = 60 + if show_cb { 36 } else { 0 } + if show_sas { 56 } else { 0 };
    let text_w = (rw - right_w - 8).max(0);

    let row = lr(x0, y, rw, 18);
    if selected {
        ctx.fill(row.x, row.y, row.w as i32, row.h as i32, pal::BUTTON_HOVER);
    }
    ctx.region(WidgetId::FriendRow(i), lr(x0, y, text_w + 4, 18));
    let label = format!("{}  {}", entry.name, friend_id_short(&entry.friend_id));
    ctx.hud_text(x0 + 4, y + 5, 1, pal::TEXT, &label, (text_w / 8).max(2) as usize);

    let mut rx = x0 + rw;
    rx -= 60;
    ctx.btn(WidgetId::FriendRemove(i), lr(rx, y + 1, 56, 16), tr(ctx.lang, "Remove", "削除"));
    if show_cb {
        rx -= 36;
        ctx.btn(
            WidgetId::FriendSelected(i),
            lr(rx, y + 1, 32, 16),
            if entry.selected_for_share { "[x]" } else { "[ ]" },
        );
    }
    if show_sas {
        rx -= 56;
        let sas = entry
            .sas_code
            .map(|c| format!("{c:06}"))
            .unwrap_or_else(|| if entry.connected { "online".into() } else { "-".into() });
        ctx.hud_text(rx, y + 5, 1, pal::TEXT_DIM, &sas, 6);
    }
}

fn friends(ctx: &mut Ctx) {
    ctx.menu_background();
    let lang = ctx.lang;
    let cx = ctx.w / 2;

    ctx.ctext(
        cx,
        8,
        2,
        pal::TEXT,
        tr(lang, "Play with Friends", "フレンドと遊ぶ"),
    );

    // Footer strip (status line + Back): content widgets that would
    // reach it are dropped instead of painting under the chrome.
    ctx.band_top = ctx.h - 40;

    let wide = ctx.w >= 620;
    let gap = 8;
    let (lx, col_w) = if wide {
        let col_w = ((ctx.w - 24) / 2).max(40);
        (8, col_w)
    } else {
        (cx - (ctx.w - 8).max(40) / 2, (ctx.w - 8).max(40))
    };
    let rx = lx + col_w + gap;
    let f = &ctx.state.friends;

    // --- "Your Friend ID" row (left column top) -----------------------
    ctx.text(
        lx + 2,
        28,
        1,
        pal::ACCENT,
        tr(lang, "Your Friend ID", "あなたのフレンドID"),
    );
    let id_y = 40;
    let id_short = if f.my_friend_id.is_empty() {
        tr(lang, "(identity not loaded)", "(IDが読み込まれていません)").to_string()
    } else {
        friend_id_short(&f.my_friend_id)
    };
    ctx.hud_text(lx + 4, id_y + 5, 1, pal::TEXT, &id_short, ((col_w - 96) / 8).max(4) as usize);
    ctx.btn(
        WidgetId::FriendsCopyId,
        lr(lx + col_w - 88, id_y, 84, 16),
        tr(lang, "Copy ID", "IDをコピー"),
    );

    // --- Add Friend row -----------------------------------------------
    // Wide: top of the right column. Narrow: under the identity row.
    let add_x = if wide { rx } else { lx };
    let add_y = if wide { 40 } else { id_y + 22 };
    if wide {
        ctx.text(
            add_x + 2,
            28,
            1,
            pal::ACCENT,
            tr(lang, "Add Friend", "フレンド追加"),
        );
    }
    let name_w = (col_w * 30 / 100).max(24);
    let add_btn_w = 52.min(col_w / 5).max(24);
    let id_w = (col_w - name_w - add_btn_w - 8).max(24);
    ctx.textfield(
        WidgetId::FriendsAddNameField,
        lr(add_x, add_y, name_w, 18),
        &f.add_name_text,
        f.add_name_field_active(),
        tr(lang, "Name", "なまえ"),
    );
    ctx.textfield(
        WidgetId::FriendsAddIdField,
        lr(add_x + name_w + 4, add_y, id_w, 18),
        &f.add_id_text,
        f.add_id_field_active(),
        "megu-id:…",
    );
    ctx.btn(
        WidgetId::FriendsAdd,
        lr(add_x + name_w + 4 + id_w + 4, add_y, add_btn_w, 18),
        tr(lang, "Add", "追加"),
    );
    if let Some(err) = &f.add_error {
        ctx.hud_text(
            add_x + 4,
            add_y + 21,
            1,
            pal::DANGER,
            err,
            ((col_w - 8) / 8).max(4) as usize,
        );
    }

    // --- Host World Sharing block (bottom-anchored, above invite) ------
    // Vertical budget: mode toggle + relay field + guest-link row +
    // link/status line ≈ 78px; the legacy invite block needs 64 more
    // and only renders when the friends list still keeps ~3 rows.
    let share_h = 88;
    let invite_h = 66;
    // Narrow: the friends-list header sits under the Add row; wide: the
    // left column's list sits under the identity row.
    let list_top = if wide { 64 } else { add_y + 34 };
    let content_bottom = ctx.band_top - 4;
    let want_invite = wide || content_bottom - list_top > share_h + invite_h + 64;
    let invite_top = if want_invite {
        content_bottom - invite_h
    } else {
        content_bottom
    };
    // Wide: sharing anchors above the invite block in the right column.
    // Narrow: it anchors above the invite block (or the footer).
    // Clamped below the fixed rows so short viewports shed the block's
    // bottom widgets (band check) instead of overlapping the Add row.
    let share_top = (invite_top - if wide { 6 } else { 4 } - share_h).max(add_y + 32);

    let share_x = if wide { rx } else { lx };
    let share_w = col_w;
    ctx.text(
        share_x + 2,
        share_top,
        1,
        pal::ACCENT,
        tr(lang, "Host World Sharing (1-hop only)", "ワールド共有（1ホップのみ）"),
    );
    let mode_y = share_top + 10;
    ctx.btn(
        WidgetId::FriendsShareMode,
        lr(share_x, mode_y, share_w, 18),
        &format!(
            "{}: {}",
            tr(lang, "Sharing", "共有"),
            f.share_mode.label(lang)
        ),
    );
    ctx.text(
        share_x + 2,
        mode_y + 22,
        1,
        pal::TEXT_DIM,
        tr(lang, "Relay Address", "リレーアドレス"),
    );
    ctx.textfield(
        WidgetId::FriendsRelayField,
        lr(share_x + 92, mode_y + 20, (share_w - 92).max(24), 18),
        &f.relay_addr_text,
        f.relay_field_active(),
        tr(lang, "host:port", "ホスト:ポート"),
    );
    let gl_y = mode_y + 42;
    let gl_w = (share_w * 3 / 5).max(24);
    ctx.btn(
        WidgetId::FriendsGenerateGuestLink,
        lr(share_x, gl_y, gl_w, 18),
        tr(lang, "Gen 128-bit Guest Link", "ゲストリンク生成"),
    );
    ctx.btn(
        WidgetId::FriendsCopyGuestLink,
        lr(share_x + gl_w + 4, gl_y, (share_w - gl_w - 4).max(24), 18),
        tr(lang, "Copy Link", "リンクをコピー"),
    );
    let link_y = gl_y + 22;
    match (&f.guest_link, &f.status) {
        (Some(link), _) => ctx.hud_text(
            share_x + 4,
            link_y,
            1,
            pal::TEXT,
            &friend_id_short(link),
            ((share_w - 8) / 8).max(4) as usize,
        ),
        (None, Some(status)) => ctx.hud_text(
            share_x + 4,
            link_y,
            1,
            pal::TEXT_DIM,
            status,
            ((share_w - 8) / 8).max(4) as usize,
        ),
        (None, None) => {}
    }

    // --- Legacy invite-code block --------------------------------------
    // Wide: bottom of the right column. Narrow: above the footer, only
    // when the friends list still gets its minimum height.
    let inv_x = if wide { rx } else { lx };
    if wide || want_invite {
        let inv_top = invite_top;
        ctx.text(
            inv_x + 2,
            inv_top,
            1,
            pal::ACCENT,
            tr(lang, "Invite Codes", "招待コード"),
        );
        let code = ctx.state.invite_display();
        ctx.text(inv_x + 4, inv_top + 12, 1, pal::TEXT, &code);
        let by = inv_top + 24;
        let bw3 = ((col_w - 12) / 3).clamp(0, 90);
        let mut bx = inv_x;
        for (id, label) in [
            (WidgetId::FriendsGenerate, tr(lang, "Generate", "生成")),
            (WidgetId::FriendsCopy, tr(lang, "Copy", "コピー")),
            (WidgetId::FriendsRevoke, tr(lang, "Revoke", "無効化")),
        ] {
            ctx.btn(id, lr(bx, by, bw3, 16), label);
            bx += bw3 + 6;
        }
        let join_btn_w = 50.min(col_w / 4).max(24);
        let field_w = (col_w - join_btn_w - 6).max(24);
        ctx.textfield(
            WidgetId::FriendsJoinField,
            lr(inv_x, by + 20, field_w, 18),
            &ctx.state.join_code_text,
            ctx.state.join_field_active(),
            "MEGU-XXXX-XXXX",
        );
        ctx.btn(
            WidgetId::FriendsJoin,
            lr(inv_x + field_w + 6, by + 20, join_btn_w, 18),
            tr(lang, "Join", "参加"),
        );
        if ctx.state.join_error {
            ctx.hud_text(
                inv_x + 4,
                by + 40,
                1,
                pal::DANGER,
                tr(
                    lang,
                    "Invalid code - expected MEGU-XXXX-XXXX",
                    "無効なコード — MEGU-XXXX-XXXX",
                ),
                ((col_w - 8) / 8).max(4) as usize,
            );
        }
    }

    // --- Friends allowlist (left column, absorbs remaining height) -----
    let list_bottom = if wide { content_bottom } else { share_top - 4 };
    ctx.text(
        lx + 2,
        list_top,
        1,
        pal::ACCENT,
        tr(lang, "Friends", "フレンド"),
    );
    let panel_top = list_top + 10;
    let panel_h = (list_bottom - panel_top).max(0);
    ctx.panel(lx, panel_top, col_w, panel_h);
    let row_h = 20;
    let body_h = (panel_h - 6).max(0);
    let mut visible = (body_h / row_h) as usize;
    if f.friends.len() > visible {
        visible = ((body_h - 18) / row_h).max(0) as usize;
    }
    let scroll = f.scroll.min(f.friends.len().saturating_sub(visible));
    if f.friends.is_empty() && panel_h >= 22 {
        ctx.ctext(
            lx + col_w / 2,
            panel_top + 8,
            1,
            pal::TEXT_DIM,
            tr(
                lang,
                "No friends yet - add a megu-id: above",
                "フレンドがいません — 上の megu-id: で追加",
            ),
        );
    }
    for row in 0..visible {
        let i = scroll + row;
        if i >= f.friends.len() {
            break;
        }
        friend_row(ctx, lx + 4, panel_top + 4 + row as i32 * row_h, col_w - 8, i);
    }
    let py = panel_top + 4 + visible as i32 * row_h;
    if f.friends.len() > visible && col_w >= 176 && py + 16 <= list_bottom {
        ctx.btn(
            WidgetId::FriendsListUp,
            lr(lx + 4, py, 60, 16),
            tr(lang, "Up", "上"),
        );
        ctx.ctext(
            lx + col_w / 2,
            py + 4,
            1,
            pal::TEXT_DIM,
            &format!("{}-{}", scroll + 1, (scroll + visible).min(f.friends.len())),
        );
        ctx.btn(
            WidgetId::FriendsListDown,
            lr(lx + col_w - 64, py, 60, 16),
            tr(lang, "Down", "下"),
        );
    }

    ctx.band_top = i32::MAX;
    // Inline status/add feedback shares the footer strip with Back.
    if let Some(status) = ctx.state.friends.status.as_deref() {
        ctx.hud_ctext(cx, ctx.h - 37, 1, pal::WARNING, status, 56);
    }
    let bw = 90.min(ctx.w - 8).max(24);
    ctx.button_unchecked(
        WidgetId::FriendsBack,
        lr(cx - bw / 2, ctx.h - 28, bw, 20),
        tr(lang, "Back", "戻る"),
        true,
    );
}

// ---------------------------------------------------------------------------
// Mod sync consent
// ---------------------------------------------------------------------------

fn mod_sync(ctx: &mut Ctx) {
    ctx.menu_background();
    let lang = ctx.lang;
    let cx = ctx.w / 2;

    ctx.ctext(
        cx,
        8,
        2,
        pal::TEXT,
        tr(lang, "Server Mod Sync", "サーバーMod同期"),
    );
    ctx.ctext(
        cx,
        30,
        1,
        pal::TEXT_DIM,
        tr(
            lang,
            "The host requests these changes - SHA-256 shown for every file",
            "ホストが以下の変更を要求 — 各ファイルのSHA-256を表示",
        ),
    );

    let pw = 400.min(ctx.w - 8).max(40);
    let px = cx - pw / 2;
    ctx.panel(px, 44, pw, 132);
    let entries = &ctx.state.pending_mod_sync;
    if entries.is_empty() {
        ctx.ctext(
            cx,
            100,
            1,
            pal::TEXT_DIM,
            tr(lang, "No pending changes.", "保留中の変更はありません。"),
        );
    } else {
        for (i, e) in entries.iter().take(7).enumerate() {
            let y = 50 + i as i32 * 17;
            // Row badges share `mod_sync_ui`'s canonical diff vocabulary
            // so the consent screen and the dedicated diff screen read
            // identically (NEW / UPDATE / REMOVE, same tints).
            let kind = match e.change {
                ModSyncChange::Added => ModSyncDiffKind::Missing,
                ModSyncChange::Updated => ModSyncDiffKind::VersionMismatch,
                ModSyncChange::Removed => ModSyncDiffKind::Removed,
            };
            let badge = kind.badge(lang);
            let bw = text_width(badge, 1) as i32;
            ctx.text(px + 8, y, 1, kind.color(), badge);
            // Mod names come from the host: sanitize control chars and
            // clip so they can't overrun the SHA column or the panel edge.
            let sha = e.short_sha().to_string();
            let name_cells =
                ((pw - 36 - bw - text_width(&sha, 1) as i32 - 8) / 8).max(1) as usize;
            ctx.hud_text(px + 16 + bw, y, 1, pal::TEXT, &e.name, name_cells);
            let sw = text_width(&sha, ctx.s as u32) as i32;
            ctx.text(px + pw - 8 - sw / ctx.s, y, 1, pal::TEXT_DIM, &sha);
        }
        if entries.len() > 7 {
            ctx.text(
                px + 8,
                50 + 7 * 17,
                1,
                pal::TEXT_DIM,
                &format!("... {} more", entries.len() - 7),
            );
        }
    }

    let (mut a, mut u, mut r) = (0usize, 0usize, 0usize);
    for e in entries {
        match e.change {
            ModSyncChange::Added => a += 1,
            ModSyncChange::Updated => u += 1,
            ModSyncChange::Removed => r += 1,
        }
    }
    ctx.ctext(
        cx,
        182,
        1,
        pal::TEXT,
        &format!(
            "{} {} | {} {} | {} {}",
            a,
            tr(lang, "added", "追加"),
            u,
            tr(lang, "updated", "更新"),
            r,
            tr(lang, "removed", "削除")
        ),
    );
    ctx.ctext(
        cx,
        196,
        1,
        pal::TEXT_DIM,
        tr(
            lang,
            "Nothing installs until you Accept",
            "承認するまで何もインストールされません",
        ),
    );

    // Buttons anchor to the bottom of the viewport so they never slide
    // off-screen on short windows (the list panel above is static).
    let missing = !ctx.state.missing_mod_deps.is_empty();
    let by = 214.min(ctx.h - 26 - if missing { 28 } else { 0 }).max(44);
    ctx.btn(
        WidgetId::ModSyncAccept,
        lr(cx - 150, by, 140, 20),
        tr(lang, "Accept & Install", "承認してインストール"),
    );
    ctx.btn(
        WidgetId::ModSyncDecline,
        lr(cx + 10, by, 140, 20),
        tr(lang, "Decline", "拒否"),
    );
    if missing {
        ctx.btn(
            WidgetId::ModSyncDownloadMissing,
            lr(cx - 120, by + 28, 240, 20),
            tr(lang, "Get Missing (Modrinth)", "不足ModをModrinthから取得"),
        );
    }
}

fn mod_sync_prompt(ctx: &mut Ctx) {
    ctx.menu_background();
    let lang = ctx.lang;
    let cx = ctx.w / 2;
    ctx.ctext(cx, 8, 2, pal::TEXT, tr(lang, "Mod Mismatch", "Modの不一致"));
    ctx.hud_text(cx - 190, 30, 1, pal::TEXT_DIM, &ctx.state.mod_sync_prompt.server_address, 48);
    let pw = 400.min(ctx.w - 8).max(40);
    let px = cx - pw / 2;
    let rows = &ctx.state.mod_sync_prompt.rows;
    let panel_h = (44 + rows.len().min(8) as i32 * 17).min((ctx.h - 112).max(44));
    ctx.panel(px, 44, pw, panel_h);
    ctx.text(px + 8, 48, 1, pal::TEXT_DIM, tr(lang, "MOD ID", "Mod ID"));
    ctx.hud_text(px + 144, 48, 1, pal::TEXT_DIM, tr(lang, "REQUIRED", "要求"), 10);
    ctx.hud_text(px + 240, 48, 1, pal::TEXT_DIM, tr(lang, "INSTALLED", "現行"), 16);
    for (i, row) in rows.iter().take(8).enumerate() {
        let y = 64 + i as i32 * 17;
        let installed = row
            .installed_version
            .as_deref()
            .unwrap_or(tr(lang, "missing", "なし"));
        ctx.hud_text(px + 8, y, 1, pal::TEXT, &row.mod_id, 16);
        ctx.hud_text(px + 144, y, 1, pal::WARNING, &row.required_version, 10);
        ctx.hud_text(px + 240, y, 1, if row.installed_version.is_some() { pal::DANGER } else { pal::TEXT_DIM }, installed, 16);
    }
    if rows.len() > 8 {
        let more = if lang == UiLang::Ja {
            format!("あと{}行", rows.len() - 8)
        } else {
            format!("... {} more", rows.len() - 8)
        };
        ctx.text(px + 8, 44 + panel_h - 10, 1, pal::TEXT_DIM, &more);
    }
    let progress_y = (44 + panel_h + 8).min(ctx.h - 62);
    ctx.hud_text(px + 8, progress_y, 1, pal::TEXT, &ctx.state.mod_sync_prompt.progress_label, 48);
    if let Some(percent) = ctx.state.mod_sync_prompt.progress_percent {
        let x = px + 8;
        let y = progress_y + 12;
        let w = (pw - 16).max(0);
        ctx.fill(x, y, w, 6, pal::TEXT_DARK);
        ctx.fill(x, y, w * i32::from(percent.min(100)) / 100, 6, pal::ACCENT);
    }
    let by = ctx.h - 44;
    ctx.btn(WidgetId::ModSyncPromptConfirm, lr(cx - 170, by, 220, 22), tr(lang, "Download & Reconnect", "ダウンロードして再接続"));
    ctx.btn(WidgetId::ModSyncPromptCancel, lr(cx + 58, by, 112, 22), tr(lang, "Cancel", "キャンセル"));
}

// ---------------------------------------------------------------------------
// Embedded screens (ModMenu + recipe browser)
//
// Both sub-screens produce their own `(UiDrawList, Vec<..HitRegion>)` in
// physical pixels. Their draw commands merge verbatim; their regions are
// re-tagged into the router's [`WidgetId`] space so `UiState` keeps a
// single, overlap-free hit list — and native chrome (the recipe
// browser's Done button) can sit on top.
// ---------------------------------------------------------------------------

fn embedded_mod_menu(ctx: &mut Ctx) {
    let (list, hits) = ctx.state.mod_menu.render(ctx.pw, ctx.ph);
    ctx.list.commands.extend(list.commands);
    ctx.regions.extend(
        hits.into_iter()
            .map(|h| HitRegion::new(WidgetId::ModMenu(h.id), h.rect)),
    );
}

fn embedded_recipe_browser(ctx: &mut Ctx) {
    let (list, hits) = ctx.state.recipe_browser.render(ctx.pw, ctx.ph);
    ctx.list.commands.extend(list.commands);
    ctx.regions.extend(
        hits.into_iter()
            .map(|h| HitRegion::new(WidgetId::Recipe(h.id), h.rect)),
    );
    // The sub-screen has no close widget of its own (Esc/gamepad-East
    // backs out); add a native Done in the header's empty top-right.
    ctx.btn(
        WidgetId::RecipeBrowserDone,
        lr((ctx.w - 60).max(4), 6, 52, 14),
        tr(ctx.lang, "Done", "完了"),
    );
}

// ---------------------------------------------------------------------------
// In-game HUD (display only — zero interactive hit regions)
// ---------------------------------------------------------------------------

fn hud(ctx: &mut Ctx) {
    let hud: &HudState = &ctx.state.hud;
    let qol = &ctx.state.settings.qol;
    let lang = ctx.lang;
    let (w, h) = (ctx.w, ctx.h);
    let cx = w / 2;

    // Opt-in MiniHUD lines — empty while disabled, so the disabled path
    // emits exactly zero commands.
    let mini_lines = if qol.mini_hud.enabled {
        format_mini_hud_lines(&qol.mini_hud, &hud.mini_hud_data)
    } else {
        Vec::new()
    };

    // Bossbars, stacked from the top (host names: sanitized + clipped).
    let boss_count = hud.bossbars.len().min(3) as i32;
    for (i, (name, frac)) in hud.bossbars.iter().take(3).enumerate() {
        let y = 6 + i as i32 * 16;
        let bw = (w - 40).clamp(8, 200);
        ctx.hud_ctext(cx, y, 1, pal::TEXT, name, ((w - 8) / 8).max(0) as usize);
        ctx.progress(
            lr(cx - bw / 2, y + 9, bw, 5),
            frac.clamp(0.0, 1.0),
            UiColor::rgb(170, 60, 200),
            UiColor::rgb(30, 20, 34),
            pal::BUTTON_BORDER,
        );
    }
    // Bottom edge of the bossbar stack (empty stack => just the top margin).
    let boss_bottom = if boss_count == 0 {
        4
    } else {
        16 * boss_count + 4
    };

    // Game-mode draw gates: vanilla creative (1) and spectator (3) hide
    // the hearts/armor/hunger/air/XP rows; spectator also drops the
    // hotbar and the crosshair. `hud_occupied_rects` mirrors this.
    let show_vitals = hud.game_mode != 1 && hud.game_mode != 3;
    let show_hotbar = hud.game_mode != 3;

    // Crosshair.
    if hud.game_mode != 3 {
        let cc = UiColor::rgba(230, 230, 230, 190);
        ctx.fill(cx - 5, h / 2, 11, 1, cc);
        ctx.fill(cx, h / 2 - 5, 1, 11, cc);
    }

    // Hotbar: offhand + 9 slots.
    let slot = 22;
    let hw = 9 * slot;
    let hx = cx - (hw + slot + 4) / 2;
    let hy = h - slot - 4;
    if show_hotbar {
        if let Some(item) = &hud.offhand {
            slot_cell(ctx, hx, hy, Some(item), false);
            if let Some(frac) = hud.item_cooldowns.get(item) {
                slot_cooldown_wipe(ctx, hx, hy, *frac);
            }
        }
        for (i, item) in hud.hotbar.iter().enumerate() {
            let sx = hx + slot + 4 + i as i32 * slot;
            slot_cell(ctx, sx, hy, item.as_ref(), i == hud.selected_slot);
            if let Some(frac) = item.as_ref().and_then(|n| hud.item_cooldowns.get(n)) {
                slot_cooldown_wipe(ctx, sx, hy, *frac);
            }
        }
    }

    // Vitals: hearts left, hunger right, above the hotbar.
    let hx0 = hx + slot + 4;
    let vy = hy - 12;
    let rx = hx0 + hw;
    if show_vitals {
        icon_row(ctx, hx0, vy, hud.health, 20.0, pal::HEALTH);
        icon_row(ctx, hx0, vy - 10, hud.armor as f32, 20.0, pal::ARMOR);
        if hud.absorption > 0.0 {
            icon_row(ctx, hx0, vy - 20, hud.absorption, 20.0, pal::ABSORPTION);
        }
        icon_row_r(ctx, rx, vy, hud.hunger as f32, 20.0, pal::HUNGER);
        if hud.air < 300 {
            icon_row_r(ctx, rx, vy - 10, hud.air as f32 / 30.0, 10.0, pal::AIR);
        }

        // XP bar + level.
        ctx.progress(
            lr(cx - 91, hy - 4, 182, 3),
            hud.xp_progress.clamp(0.0, 1.0),
            pal::XP,
            UiColor::rgb(20, 30, 14),
            pal::BUTTON_BORDER,
        );
        if hud.xp_level > 0 {
            ctx.ctext(cx, hy - 14, 1, pal::XP, &hud.xp_level.to_string());
        }
    }

    // ------------------------------------------------------------------
    // Lower-screen stacking. Everything bottom-anchored shares one
    // collision model so overlays can never overlap:
    //   * the vitals icon columns flank the hotbar (always drawn),
    //   * the actionbar sits centered at a fixed band above them,
    //   * subtitles stack upward from the hotbar on the right, and
    //   * the crafting-conflict button and the MiniHUD box stack above
    //     whatever came before (or drop lines that cannot fit).
    // ------------------------------------------------------------------
    let hotbar_top = hy - 4;
    // Hearts/armor/(absorption) column left, hunger/(air) column right —
    // empty ranges while creative/spectator keeps the rows undrawn so no
    // overlay ever lifts for invisible chrome.
    let (vl, vr) = if show_vitals {
        (hx0..(hx0 + 80), (rx - 80)..rx)
    } else {
        (0..0, 0..0)
    };
    let vtop_l = vy - if hud.absorption > 0.0 { 20 } else { 10 };
    let vtop_r = vy - if hud.air < 300 { 10 } else { 0 };

    // Actionbar: one centered line in the band directly above the vitals.
    let abar = if hud.actionbar.is_empty() {
        None
    } else {
        let text = hud_str(&hud.actionbar, ((w - 8) / 8).max(0) as usize);
        let aw = text_width(&text, 1) as i32;
        ctx.ctext(cx, hy - 44, 1, pal::TEXT, &text);
        Some(cx - aw / 2..cx + aw / 2)
    };
    // Band the actionbar text occupies (used to clip colliding rows).
    let abar_band = (hy - 44)..(hy - 36);
    // Drawn subtitle rows as `(fill_left, y)` — chat clips around them.
    let mut subtitle_rows: Vec<(i32, i32)> = Vec::new();
    // Leftmost x of the right-hand stack (subtitles, conflict button):
    // corner boxes reaching into it must stay above `stack_bottom`.
    let mut stack_left = w;

    // Directional accessibility subtitles (opt-in): up to 4 compact
    // right-aligned rows stacked above the hotbar — "< sound" left,
    // "sound >" right, "v sound" behind, no marker when centered.
    // The stack lifts above the right vitals column when a row reaches
    // it, and again above the actionbar when it shares that band; rows
    // still outside the viewport are dropped, never drawn off-screen.
    let mut stack_bottom = hotbar_top;
    if qol.show_subtitles && !hud.subtitles.is_empty() {
        let shown: Vec<&HudSubtitle> = hud.subtitles.iter().rev().take(4).collect();
        let build_rows = |base: i32| -> Vec<(String, i32)> {
            shown
                .iter()
                .enumerate()
                .map(|(i, sub)| {
                    let label = match sub.direction {
                        SubtitleDirection::Left => format!("< {}", sub.label),
                        SubtitleDirection::Center => sub.label.clone(),
                        SubtitleDirection::Right => format!("{} >", sub.label),
                        SubtitleDirection::Behind => format!("v {}", sub.label),
                    };
                    // Newest row at the bottom.
                    let y = base - (shown.len() - i) as i32 * 10;
                    let cells = ((w - 14) / 8).max(1) as usize;
                    (hud_str(&label, cells), y)
                })
                .collect()
        };
        let mut sub_base = hotbar_top;
        let mut rows = build_rows(sub_base);
        // A row whose left edge reaches into either vitals column
        // (hearts/armor left, hunger/air right) lifts the whole stack
        // above that column — the label is never cut by an icon.
        for (i, (label, y)) in rows.iter().enumerate() {
            let rw = text_width(label, 1) as i32 + 6;
            if w - 4 - rw < vr.end && *y < vy + 8 && *y + 10 > vtop_r {
                sub_base = sub_base.min(vtop_r - 10 + (shown.len() - i) as i32 * 10);
            }
            if w - 4 - rw < vl.end && *y < vy + 8 && *y + 10 > vtop_l {
                sub_base = sub_base.min(vtop_l - 10 + (shown.len() - i) as i32 * 10);
            }
        }
        rows = build_rows(sub_base);
        if abar.is_some()
            && rows.iter().any(|(label, y)| {
                let rw = text_width(label, 1) as i32 + 6;
                *y < abar_band.end
                    && *y + 10 > abar_band.start
                    && w - 4 - rw < abar.as_ref().map_or(i32::MAX, |ab| ab.end)
            })
        {
            sub_base = (hy - 46).min(sub_base);
            rows = build_rows(sub_base);
        }
        // Drop rows that still cannot fit inside the viewport rather
        // than emitting off-screen commands.
        let rows: Vec<(String, i32)> = rows
            .into_iter()
            .filter(|(_, y)| *y >= 0 && *y + 10 <= h)
            .collect();
        for (label, y) in &rows {
            let rw = text_width(label, 1) as i32 + 6;
            ctx.fill(w - 4 - rw, *y, rw, 10, UiColor::rgba(0, 0, 0, 110));
            ctx.text(w - 4 - rw + 3, *y + 1, 1, pal::TEXT, label);
        }
        // Rows' x ranges for the chat clip below.
        subtitle_rows = rows
            .iter()
            .map(|(label, y)| (w - 4 - (text_width(label, 1) as i32 + 6), *y))
            .collect();
        for (sx, _) in &subtitle_rows {
            stack_left = stack_left.min(*sx);
        }
        // Anything else bottom-right stacks above the subtitle block.
        stack_bottom = sub_base - shown.len() as i32 * 10 - 2;
    }

    // Crafting-conflict switcher: exactly one compact `< k/N >` cycle
    // button while the game reports two or more candidate recipes —
    // right-aligned above the subtitle stack, lifted clear of the right
    // vitals column when it reaches it. `total_candidates <= 1` emits
    // no commands and no region at all.
    if hud.crafting_conflict.is_active() {
        let label = format!(
            "< {}/{} >",
            hud.crafting_conflict.selected() + 1,
            hud.crafting_conflict.total_candidates
        );
        let bw = (text_width(&label, 1) as i32 + 8).min(w - 8);
        let bx = w - 4 - bw;
        let mut bottom = stack_bottom - 2;
        if bx < vl.end {
            bottom = bottom.min(vtop_l - 2);
        }
        if bx < vr.end {
            bottom = bottom.min(vtop_r - 2);
        }
        let by = (bottom - 14).max(2);
        ctx.btn(WidgetId::CraftConflictNext, lr(bx, by, bw, 14), &label);
        stack_left = stack_left.min(bx);
        stack_bottom = by - 2;
    }

    // Chat scrollback, bottom-left. Lines clip to the viewport, to the
    // left vitals column, to the actionbar, and to whatever subtitle row
    // shares their band. While the scroll-lock is engaged the window
    // shifts `scroll_offset` lines up and the freed bottom slot carries
    // the "+N new" badge instead of the newest line.
    let scroll_locked = qol.chat_scroll_lock && ctx.state.chat_scroll.scrolled_up;
    let scroll_off = if scroll_locked {
        ctx.state.chat_scroll.scroll_offset
    } else {
        0
    };
    let chat_take = if scroll_locked { 5 } else { 6 };
    let mut chat_top = i32::MAX;
    let mut chat_right = 0i32;
    for (k, line) in hud
        .chat_lines
        .iter()
        .rev()
        .skip(scroll_off)
        .take(chat_take)
        .enumerate()
    {
        let i = k + usize::from(scroll_locked);
        let y = hy - 12 - i as i32 * 10;
        let (band_top, band_bot) = (y - 1, y + 9);
        let mut cells = ((w - 14) / 8).max(0) as usize;
        if band_top < vy + 8 && band_bot > vtop_l {
            cells = cells.min(((vl.start - 10) / 8).max(0) as usize);
        }
        if let Some(ab) = &abar {
            if band_top < abar_band.end && band_bot > abar_band.start {
                cells = cells.min(((ab.start - 10) / 8).max(0) as usize);
            }
        }
        for (sx, sy) in &subtitle_rows {
            if band_top < *sy + 10 && band_bot > *sy {
                cells = cells.min(((*sx - 10) / 8).max(0) as usize);
            }
        }
        if cells == 0 {
            continue;
        }
        let text = hud_str(line, cells);
        let tw = text_width(&text, 1) as i32;
        ctx.fill(2, y - 1, tw + 6, 10, UiColor::rgba(0, 0, 0, 110));
        ctx.text(4, y, 1, pal::TEXT, &text);
        chat_top = chat_top.min(y - 1);
        chat_right = chat_right.max(8 + tw);
    }
    // Scroll-lock badge in the freed bottom slot.
    if scroll_locked && hy - 12 >= 0 {
        let badge = ctx
            .state
            .chat_scroll
            .unread_label(lang)
            .unwrap_or_else(|| tr(lang, "scrolled", "保持中").to_string());
        let bw = text_width(&badge, 1) as i32 + 6;
        ctx.fill(2, hy - 13, bw + 2, 10, UiColor::rgba(0, 0, 0, 110));
        ctx.text(4, hy - 12, 1, pal::WARNING, &badge);
        chat_top = chat_top.min(hy - 13);
        chat_right = chat_right.max(8 + bw);
    }

    // Chat/command input bar (open chat screen): a dark input strip at
    // the bottom-left with a caret, plus the vanilla-style suggestion
    // popup stacked above it listing `completions` with the applied
    // candidate highlighted.
    if hud.chat_input.open {
        let box_w = ((w * 3) / 5).clamp(80, w - 8);
        let box_y = h - 13;
        ctx.fill(2, box_y, box_w, 11, UiColor::rgba(0, 0, 0, 160));
        ctx.border(2, box_y, box_w, 11, pal::PANEL_BORDER);
        let cells = ((box_w - 8) / 8).max(0) as usize;
        let text = hud_str(&hud.chat_input.text, cells);
        ctx.text(4, box_y + 2, 1, pal::TEXT, &text);
        let caret = hud.chat_input.cursor().min(cells);
        let caret_x = (4 + caret as i32 * 8).min(2 + box_w - 3);
        ctx.fill(caret_x, box_y + 2, 1, 7, pal::TEXT);
        let rows = hud.chat_input.completions.len().min(10);
        if rows > 0 {
            let widest = hud
                .chat_input
                .completions
                .iter()
                .take(rows)
                .map(|cand| crate::draw::text_width(&hud_str(cand, 40), 1) as i32)
                .max()
                .unwrap_or(0);
            let pop_w = (widest + 8).min(w - 8);
            let pop_h = rows as i32 * 10 + 2;
            let pop_y = (box_y - 2 - pop_h).max(2);
            let selected = hud.chat_input.selected_completion();
            ctx.fill(4, pop_y, pop_w, pop_h, UiColor::rgba(8, 10, 14, 220));
            ctx.border(4, pop_y, pop_w, pop_h, pal::PANEL_BORDER);
            for (i, cand) in hud.chat_input.completions.iter().take(rows).enumerate() {
                let ry = pop_y + 1 + i as i32 * 10;
                if Some(i) == selected {
                    ctx.fill(5, ry, pop_w - 2, 10, UiColor::rgba(80, 88, 110, 120));
                }
                ctx.hud_text(
                    7,
                    ry + 1,
                    1,
                    pal::TEXT,
                    cand,
                    ((pop_w - 10) / 8).max(1) as usize,
                );
            }
        }
    }

    // Player list overlay (hold-Tab): stacked below the bossbars and
    // height-capped to the viewport with a "+N more" tail.
    if hud.show_player_list {
        let pw = 200.min(w - 8).max(70);
        let px = cx - pw / 2;
        let py = boss_bottom + 4;
        let name_cells = ((pw - 60) / 8).max(1) as usize;
        let rows_avail = ((h - 4 - (py + 14)) / 11).max(0) as usize;
        let (shown, extra) = if hud.players.len() <= rows_avail {
            (hud.players.len(), 0usize)
        } else {
            let s = rows_avail.saturating_sub(1);
            (s, hud.players.len() - s)
        };
        let ph = 14 + (shown + usize::from(extra > 0)) as i32 * 11;
        ctx.panel(px, py, pw, ph.max(14));
        ctx.ctext(
            cx,
            py + 4,
            1,
            pal::TEXT,
            &format!(
                "{} ({})",
                tr(lang, "Players", "プレイヤー"),
                hud.players.len()
            ),
        );
        for (i, (name, ping)) in hud.players.iter().take(shown).enumerate() {
            let y = py + 14 + i as i32 * 11;
            ctx.hud_text(px + 6, y, 1, pal::TEXT, name, name_cells);
            ping_bars(ctx, px + pw - 30, y, *ping);
            ctx.text(px + pw - 52, y, 1, pal::TEXT_DIM, &format!("{ping}ms"));
        }
        if extra > 0 {
            ctx.text(
                px + 6,
                py + 14 + shown as i32 * 11,
                1,
                pal::TEXT_DIM,
                &format!("+{extra} more"),
            );
        }
    }

    if mini_lines.is_empty() {
        ctx.text(4, 4, 1, pal::TEXT_DIM, "megu HUD");
    }

    // MagicHUD occupies the centered bottom stack and the top-right
    // status column at its own internal scale; convert to logical px so
    // the MiniHUD box can stack around it.
    let magic_frame = magic_frame(
        &hud.magic,
        (ctx.w * ctx.s) as u32,
        (ctx.h * ctx.s) as u32,
        ctx.s,
    );

    // MiniHUD: translucent backing + clipped lines anchored to the
    // configured corner. The box is width-capped against the centered
    // player list and height-capped against the top stacks (bossbars,
    // magic statuses) and bottom stacks (chat, subtitles, conflict
    // button, vitals, hotbar, magic bars); lines that cannot fit are
    // dropped rather than drawn on top of another element.
    if !mini_lines.is_empty() {
        let pad = 3;
        let anchor = qol.mini_hud.anchor;
        let mut max_box_w = (w - 8).max(8);
        if hud.show_player_list {
            max_box_w = max_box_w.min(cx - 106).max(8);
        }
        let max_chars = ((max_box_w - 2 * pad) / 8).max(1) as usize;
        let clipped: Vec<String> = mini_lines
            .iter()
            .map(|line| hud_str(line, max_chars))
            .collect();
        let text_w = clipped
            .iter()
            .map(|line| text_width(line, 1) as i32)
            .max()
            .unwrap_or(0);
        let box_w = (text_w + 2 * pad).min(max_box_w);
        let bx = match anchor {
            MiniHudAnchor::TopLeft | MiniHudAnchor::BottomLeft => 4,
            MiniHudAnchor::TopRight | MiniHudAnchor::BottomRight => (w - 4 - box_w).max(4),
        };
        let box_x = bx..(bx + box_w);

        // Nothing may cross below these elements:
        let mut top_edge = 4;
        // Bossbars sit centered at the top.
        if box_x.start < cx + 104 && box_x.end > cx - 104 {
            top_edge = top_edge.max(boss_bottom + 2);
        }
        let mut bottom_edge = match anchor {
            MiniHudAnchor::TopLeft | MiniHudAnchor::TopRight => h - 4,
            MiniHudAnchor::BottomLeft => hotbar_top,
            MiniHudAnchor::BottomRight => stack_bottom,
        };
        // The right stack (subtitles + conflict button) bounds anything
        // reaching its column on the right.
        if box_x.end > stack_left && box_x.start < w - 4 {
            bottom_edge = bottom_edge.min(stack_bottom);
        }
        // Vitals icon columns.
        if box_x.start < vl.end && box_x.end > vl.start {
            bottom_edge = bottom_edge.min(vtop_l - 2);
        }
        if box_x.start < vr.end && box_x.end > vr.start {
            bottom_edge = bottom_edge.min(vtop_r - 2);
        }
        // Hotbar slot cells + XP bar + actionbar band are center-bottom.
        if box_x.start < rx && box_x.end > hx {
            bottom_edge = bottom_edge.min(if abar.is_some() { hy - 46 } else { hy - 2 });
        }
        // Chat occupies the left band up to its widest drawn line.
        if chat_right > 0 && box_x.start < chat_right {
            bottom_edge = bottom_edge.min(chat_top - 2);
        }
        // MagicHUD: centered bottom bars + top-right status badges.
        if let Some(mf) = &magic_frame {
            if box_x.start < mf.panel.end && box_x.end > mf.panel.start {
                bottom_edge = bottom_edge.min(mf.stack_top - 2);
            }
            if box_x.start < mf.statuses.end && box_x.end > mf.statuses.start {
                top_edge = top_edge.max(mf.status_bottom + 2);
            }
        }

        let avail = bottom_edge - top_edge;
        let max_lines = ((avail - 2 * pad + 2) / 10).max(0) as usize;
        if max_lines > 0 {
            let shown: Vec<&String> = clipped.iter().take(max_lines).collect();
            let text_w = shown
                .iter()
                .map(|line| text_width(line, 1) as i32)
                .max()
                .unwrap_or(0);
            let box_w = (text_w + 2 * pad).min(max_box_w);
            let bx = match anchor {
                MiniHudAnchor::TopLeft | MiniHudAnchor::BottomLeft => 4,
                MiniHudAnchor::TopRight | MiniHudAnchor::BottomRight => (w - 4 - box_w).max(4),
            };
            let box_h = 2 * pad + shown.len() as i32 * 10 - 2;
            let by = match anchor {
                MiniHudAnchor::TopLeft | MiniHudAnchor::TopRight => top_edge,
                _ => bottom_edge - box_h,
            };
            ctx.fill(bx, by, box_w, box_h, UiColor::rgba(0, 0, 0, 110));
            for (i, line) in shown.iter().enumerate() {
                ctx.text(bx + pad, by + pad + i as i32 * 10, 1, pal::TEXT, line);
            }
        }
    }

    if !hud.magic.is_empty() {
        let overlay = crate::magic_hud::build_magic_hud_draw_list(
            &hud.magic,
            (ctx.w * ctx.s) as u32,
            (ctx.h * ctx.s) as u32,
        );
        for command in overlay.commands {
            if let UiCommand::Text {
                x,
                y,
                scale,
                color,
                ref text,
            } = command
            {
                ctx.list.text_str(x, y, scale, color, text);
            } else {
                ctx.list.push(command);
            }
        }
    }
}

/// The screen space MagicHUD claims (mirroring `magic_hud.rs`'s internal
/// scale math) so other overlays can stack around it.
struct MagicFrame {
    /// Centered mana/cast/cooldown panel column, logical px.
    panel: std::ops::Range<i32>,
    /// Top of that bottom stack, logical px.
    stack_top: i32,
    /// Top-right status-badge column, logical px.
    statuses: std::ops::Range<i32>,
    /// Bottom of the badge stack, logical px.
    status_bottom: i32,
}

fn magic_frame(magic: &MagicHudState, vpw: u32, vph: u32, s: i32) -> Option<MagicFrame> {
    if magic.is_empty() || vpw < 80 || vph < 140 {
        return None;
    }
    let ms = (vph / 360).clamp(1, 4).min((vpw / 320).max(1)) as i32;
    let (mw, mh) = (vpw as i32 / ms, vph as i32 / ms);
    let to_logical = |v: i32| v * ms / s;
    let panel_w = 194.min(mw - 16);
    let panel_left = (mw - panel_w) / 2;
    let has_cooldowns = magic.cooldowns.iter().any(|c| c.remaining_ticks > 0);
    let stack_top = if has_cooldowns {
        mh - 128
    } else if magic.active_cast.is_some() {
        mh - 98
    } else if magic.max_mana.is_finite() && magic.max_mana > 0.0 {
        mh - 68
    } else {
        mh - 38
    };
    let status_rows = ((stack_top - 10) / 19).max(0) as usize;
    let n_status = magic
        .custom_statuses
        .iter()
        .filter(|st| st.remaining_ticks > 0)
        .take(6usize.min(status_rows))
        .count() as i32;
    let status_w = 156.min(mw - 16);
    Some(MagicFrame {
        panel: to_logical(panel_left)..to_logical(panel_left + panel_w),
        stack_top: to_logical(stack_top),
        statuses: to_logical(mw - 8 - status_w)..to_logical(mw),
        status_bottom: to_logical(8 + n_status * 19 - 3),
    })
}

// ---------------------------------------------------------------------------
// Spatial subtitle overlay (composited after the HUD layout pass)
// ---------------------------------------------------------------------------

/// Append the spatial-subtitle panel to the HUD draw list.
///
/// `subtitles` is the cue state an embedder feeds from audio events
/// (`client-app`'s `SpatialSubtitleCue` → [`SubtitleHudState::push`]);
/// `state.settings.qol.show_subtitles` is the same opt-in the legacy
/// `hud.subtitles` rows honor. Emits nothing — and returns `false` —
/// while the setting is off or no cue is live. `out` is appended to, so
/// call this after [`UiState::render_into`]/[`layout_screen`]; the panel
/// stacks above every rectangle [`hud_occupied_rects`] reports (hotbar,
/// vitals, XP, actionbar, chat, bossbars, player list, MagicHUD, the
/// legacy subtitle rows, and the crafting-conflict button) and never
/// registers hit regions — subtitles are display-only.
pub fn layout_subtitle_hud(
    state: &UiState,
    subtitles: &SubtitleHudState,
    width: u32,
    height: u32,
    out: &mut UiDrawList,
) -> bool {
    let mut reserved = Vec::new();
    layout_subtitle_hud_with_scratch(state, subtitles, width, height, out, &mut reserved)
}

/// Buffer-reusing form of [`layout_subtitle_hud`]. `reserved` keeps its
/// allocation across frames and is refilled with the same occupancy geometry.
pub fn layout_subtitle_hud_with_scratch(
    state: &UiState,
    subtitles: &SubtitleHudState,
    width: u32,
    height: u32,
    out: &mut UiDrawList,
    reserved: &mut Vec<UiRect>,
) -> bool {
    if !state.settings.qol.show_subtitles || subtitles.is_empty() {
        return false;
    }
    hud_occupied_rects_into(state, width, height, reserved);
    subtitles.render_avoiding(width as f32, height as f32, reserved, out)
}

// ---------------------------------------------------------------------------
// HUD feature overlays: scoreboard sidebar, title, looking-at block
// ---------------------------------------------------------------------------
//
// These composite after [`layout_screen`] exactly like
// [`layout_subtitle_hud`]: each reads its slice of [`HudState`], emits
// nothing while the feature is unpopulated/disabled, and appends to `out`.
// The scoreboard and title reuse the landed `hud_widgets` pack through a
// minimal [`HudSnapshot`] (vitals explicitly disabled so the widget
// renderer never double-draws the hotbar chrome `hud()` already emits);
// the looking-at panel is drawn directly since the widget pack has no
// Jade-style element.

/// Vanilla-style empty snapshot for single-widget renders: every widget
/// off except the one the caller fills in.
fn hud_feature_snapshot() -> HudSnapshot {
    HudSnapshot {
        // `show_vitals = false` + zero XP suppresses every vitals
        // element; the remaining widgets default to empty/hidden.
        vitals: crate::hud_widgets::VitalsState {
            show_vitals: false,
            ..Default::default()
        },
        ..Default::default()
    }
}

/// Append the scoreboard sidebar (`hud.scoreboard`) to the HUD draw
/// list: right-edge panel, objective title, score-descending rows capped
/// at the vanilla 15. Returns `false` — emitting nothing — while the
/// state is hidden or empty.
pub fn layout_scoreboard_sidebar(
    state: &UiState,
    width: u32,
    height: u32,
    out: &mut UiDrawList,
) -> bool {
    let scoreboard = &state.hud.scoreboard;
    if !scoreboard.should_render() {
        return false;
    }
    let mut snapshot = hud_feature_snapshot();
    snapshot.scoreboard = scoreboard.sidebar();
    let before = out.len();
    HudWidgetsRenderer::new().render(&snapshot, width, height, out);
    out.len() > before
}

/// Append the title/subtitle overlay (`hud.title`) to the HUD draw list:
/// the big title and subtitle centered in the upper third with vanilla
/// fade-in/hold/fade-out alpha driven by
/// [`TitleOverlayState::tick`](crate::state::TitleOverlayState::tick).
/// Returns `false` once the overlay has fully expired.
pub fn layout_title_overlay(
    state: &UiState,
    width: u32,
    height: u32,
    out: &mut UiDrawList,
) -> bool {
    let Some(overlay) = state.hud.title_overlay.overlay() else {
        return false;
    };
    let mut snapshot = hud_feature_snapshot();
    snapshot.title = overlay;
    let before = out.len();
    HudWidgetsRenderer::new().render(&snapshot, width, height, out);
    out.len() > before
}

/// Append the vanilla two-column F3 debug overlay
/// (`hud.debug_overlay`) to the HUD draw list: left column at top-left,
/// right column at top-right, exactly like [`Ctx::debug`]'s own claim
/// bookkeeping. Returns `false` while `enabled` is off.
pub fn layout_debug_overlay(
    state: &UiState,
    width: u32,
    height: u32,
    out: &mut UiDrawList,
) -> bool {
    let overlay = &state.hud.debug_overlay;
    if !overlay.enabled {
        return false;
    }
    let mut snapshot = hud_feature_snapshot();
    snapshot.debug = overlay.clone();
    let before = out.len();
    HudWidgetsRenderer::new().render(&snapshot, width, height, out);
    out.len() > before
}

/// Append the Jade-style looking-at-block panel (`hud.jade_looking_at`)
/// to the HUD draw list: a compact top-left tooltip with the targeted
/// block's name, mod/position info, tool hint, and mod-provided extra
/// lines. Returns `false` while disabled or targeting nothing.
pub fn layout_looking_at(state: &UiState, width: u32, height: u32, out: &mut UiDrawList) -> bool {
    let looking = &state.hud.looking_at;
    if !looking.is_visible() {
        return false;
    }
    // Same auto GUI scale the other corner overlays use so panels agree.
    let ms = ((height as f32 / 360.0).floor() as u32)
        .clamp(1, 4)
        .min(((width as f32 / 320.0).floor() as u32).max(1));
    let lw = (width / ms) as i32;
    let lh = (height / ms) as i32;
    if lw < 48 || lh < 44 {
        return false;
    }

    // Content lines: name, then dim mod/position info, tool hint, and
    // capped extra tooltip lines.
    let mut lines: Vec<(String, UiColor)> = Vec::new();
    let name_cells = ((lw / 2 - 12) / 8).max(1) as usize;
    lines.push((hud_str(looking.name(), name_cells), pal::TEXT));
    let mut info_parts: Vec<String> = Vec::new();
    if let Some(mod_name) = looking.mod_name.as_ref().filter(|m| !m.is_empty()) {
        info_parts.push(hud_str(mod_name, 24));
    }
    if let Some([x, y, z]) = looking.position {
        info_parts.push(format!("{x} {y} {z}"));
    }
    if !info_parts.is_empty() {
        lines.push((info_parts.join("  "), pal::TEXT_DIM));
    }
    if let Some(hint) = looking.tool_hint.as_ref().filter(|t| !t.is_empty()) {
        lines.push((hud_str(hint, name_cells), pal::WARNING));
    }
    for extra in looking
        .extra_lines
        .iter()
        .filter(|l| !l.is_empty())
        .take(crate::magic_hud::LOOKING_AT_MAX_EXTRA_LINES)
    {
        lines.push((hud_str(extra, name_cells), pal::TEXT_DIM));
    }

    const EDGE_L: i32 = 4;
    const ROW_H: i32 = 10;
    const PAD_X: i32 = 4;
    const PAD_Y: i32 = 3;
    // Rows that fit above the bottom edge; oldest extras drop first is
    // wrong here — extras are already capped, so tail rows drop instead.
    let max_rows = ((lh - 2 * EDGE_L) / ROW_H).max(0) as usize;
    let shown = lines.len().min(max_rows);
    if shown == 0 {
        return false;
    }
    let lines = &lines[..shown];
    let panel_w = lines
        .iter()
        .map(|(text, _)| text_width(text, 1) as i32)
        .max()
        .unwrap_or(0)
        + 2 * PAD_X;
    let panel_h = shown as i32 * ROW_H + 2 * PAD_Y - 2;
    if panel_w > lw - 2 * EDGE_L || panel_h > lh - 2 * EDGE_L {
        return false;
    }

    // Reserved HUD chrome in this overlay's logical space; the panel
    // slides down past whatever it would intersect (top-left anchor).
    let reserved: Vec<UiRect> = hud_occupied_rects(state, width, height)
        .iter()
        .map(|r| {
            let x0 = (r.x as f32 / ms as f32).floor() as i32;
            let y0 = (r.y as f32 / ms as f32).floor() as i32;
            let x1 = (r.right() as f32 / ms as f32).ceil() as i32;
            let y1 = (r.bottom() as f32 / ms as f32).ceil() as i32;
            UiRect::new(x0, y0, (x1 - x0).max(0) as u32, (y1 - y0).max(0) as u32)
        })
        .collect();
    let panel_x = EDGE_L;
    let mut top = EDGE_L;
    loop {
        let rect = UiRect::new(panel_x, top, panel_w as u32, panel_h as u32);
        match reserved.iter().find(|r| rect.intersects(**r)) {
            Some(r) => top = r.bottom() + 2,
            None => break,
        }
        if top + panel_h > lh - EDGE_L {
            return false;
        }
    }

    let px = panel_x * ms as i32;
    let py = top * ms as i32;
    let pw = (panel_w * ms as i32) as u32;
    let ph = (panel_h * ms as i32) as u32;
    out.fill_rect(UiRect::new(px, py, pw, ph), pal::PANEL);
    out.border_rect(UiRect::new(px, py, pw, ph), pal::PANEL_BORDER, ms);
    for (i, (text, color)) in lines.iter().enumerate() {
        let budget = (panel_w - 2 * PAD_X).max(0) as usize;
        let clipped = crate::draw::first_px(text, budget);
        if clipped.is_empty() {
            continue;
        }
        out.text_str(
            (panel_x + PAD_X) * ms as i32,
            (top + PAD_Y + i as i32 * ROW_H) * ms as i32,
            ms,
            *color,
            clipped,
        );
    }
    true
}

/// Append the server-driven sign-edit overlay (`state.sign_editor`) to
/// the draw list: a full-screen dim behind a centered wooden panel with
/// the `Edit Sign Message` / `看板のテキスト編集` header, the four
/// editable lines (active line highlighted, char-cell caret at the
/// cursor), and a `[Done]` hint. Returns `false` while no session is
/// open; panel geometry is clamped into the viewport so nothing draws
/// outside `width`×`height` at any size.
pub fn layout_sign_editor(
    state: &UiState,
    width: u32,
    height: u32,
    out: &mut UiDrawList,
) -> bool {
    let Some(editor) = &state.sign_editor else {
        return false;
    };
    // Same auto GUI scale the other HUD overlays use so panels agree.
    let ms = ((height as f32 / 360.0).floor() as u32)
        .clamp(1, 4)
        .min(((width as f32 / 320.0).floor() as u32).max(1));
    let lw = (width / ms) as i32;
    let lh = (height / ms) as i32;

    const EDGE: i32 = 8;
    const TITLE_H: i32 = 14;
    const ROW_H: i32 = 13;
    const HINT_H: i32 = 14;
    const PAD: i32 = 6;
    let rows_h = ROW_H * SIGN_LINE_COUNT as i32;
    let panel_w = (lw - 2 * EDGE).clamp(0, 300);
    let panel_h = (lh - 2 * EDGE).clamp(0, TITLE_H + rows_h + HINT_H + 2 * PAD);
    if panel_w < 32 || panel_h < 32 {
        return false;
    }
    let px_l = ((lw - panel_w) / 2).max(EDGE.min(lw - panel_w));
    let py_l = ((lh - panel_h) / 2).max(EDGE.min(lh - panel_h));

    // Vanilla sign-edit backdrop: the world dims behind the editor.
    out.fill_rect(
        UiRect::new(0, 0, width, height),
        UiColor::rgba(0, 0, 0, 128),
    );

    let px = px_l * ms as i32;
    let py = py_l * ms as i32;
    let pw = (panel_w * ms as i32) as u32;
    let ph = (panel_h * ms as i32) as u32;
    // Oak-sign wood: light plank fill, darker frame + line slots.
    const WOOD: UiColor = UiColor::rgb(168, 124, 72);
    const WOOD_DARK: UiColor = UiColor::rgb(104, 72, 40);
    const WOOD_SLOT: UiColor = UiColor::rgb(140, 100, 58);
    const WOOD_SLOT_ACTIVE: UiColor = UiColor::rgb(188, 142, 86);
    const INK: UiColor = UiColor::rgb(34, 24, 12);
    out.fill_rect(UiRect::new(px, py, pw, ph), WOOD);
    out.border_rect(UiRect::new(px, py, pw, ph), WOOD_DARK, ms);

    let inner_w = panel_w - 2 * PAD;
    let title = tr(
        state.lang(),
        "Edit Sign Message",
        "看板のテキスト編集",
    );
    let title = crate::draw::first_px(title, inner_w.max(0) as usize);
    let title_w = text_width(title, ms) as i32;
    let title_y = (py_l + PAD + (TITLE_H - 8) / 2) * ms as i32;
    out.text_str(px + (pw as i32 - title_w) / 2, title_y, ms, INK, title);

    // Four text lines: the active row gets a brighter slot + caret.
    let rows_y = py_l + PAD + TITLE_H;
    for (i, line) in editor.lines().iter().enumerate() {
        let ry = rows_y + i as i32 * ROW_H;
        if ry + ROW_H > py_l + panel_h - HINT_H - 2 {
            break;
        }
        let active = i == editor.active_line();
        let slot = UiRect::new(
            (px_l + PAD) * ms as i32,
            ry * ms as i32,
            (inner_w * ms as i32) as u32,
            (ROW_H - 2) as u32 * ms,
        );
        out.fill_rect(slot, if active { WOOD_SLOT_ACTIVE } else { WOOD_SLOT });
        if active {
            out.border_rect(slot, UiColor::rgb(238, 226, 190), ms.max(1));
        }
        let text_pad = 3;
        let budget = (inner_w - 2 * text_pad).max(0) as usize;
        let clipped = crate::draw::first_px(line, budget);
        let tx = (px_l + PAD + text_pad) * ms as i32;
        let ty = (ry + (ROW_H - 2 - 8) / 2) * ms as i32;
        out.text_str(tx, ty, ms, INK, clipped);
        if active {
            // Caret: 1-cell sliver at the cursor's cell offset inside the
            // clipped text, clamped into the slot's right edge.
            let prefix_text: String = line.chars().take(editor.cursor_col()).collect();
            let prefix = crate::draw::first_px(&prefix_text, budget);
            let caret_x = (tx + text_width(prefix, ms) as i32)
                .min(slot.right() - ms as i32)
                .max(tx);
            out.fill_rect(
                UiRect::new(caret_x, ty, ms, 8 * ms),
                UiColor::rgb(240, 232, 210),
            );
        }
    }

    // Bottom hint row.
    let hint = tr(state.lang(), "[Done]", "[完了]");
    let hint = crate::draw::first_px(hint, inner_w.max(0) as usize);
    let hint_w = text_width(hint, ms) as i32;
    let hint_y = (py_l + panel_h - PAD - (HINT_H + 8) / 2) * ms as i32;
    if hint_y >= title_y + 8 * ms as i32 {
        out.text_str(px + (pw as i32 - hint_w) / 2, hint_y, ms, INK, hint);
    }
    true
}

/// Append the toast-notification stack (`state.toasts`) to the draw
/// list: a bounded, right-anchored stack with a severity stripe and
/// fade alpha — display-only, no hit regions. On the in-game HUD every
/// toast slides below whatever [`hud_occupied_rects`] reports
/// (bossbars, MagicHUD status badges); menu screens keep the free
/// top-right corner. Returns `false` — emitting nothing — while
/// `settings.qol.toast_notifications` is off or the queue is empty.
pub fn layout_toast_stack(state: &UiState, width: u32, height: u32, out: &mut UiDrawList) -> bool {
    if !state.settings.qol.toast_notifications || state.toasts.is_empty() {
        return false;
    }
    // Same auto GUI scale the other corner overlays use.
    let ms = ((height as f32 / 360.0).floor() as u32)
        .clamp(1, 4)
        .min(((width as f32 / 320.0).floor() as u32).max(1));
    let lw = (width / ms) as i32;
    let lh = (height / ms) as i32;
    if lw < 64 || lh < 48 {
        return false;
    }

    const EDGE: i32 = 4;
    const ROW_H: i32 = 10;
    const PAD: i32 = 3;
    const STRIPE_W: i32 = 3;
    let max_w = (lw / 2).clamp(40, 190);
    let text_cells = ((max_w - 2 * PAD - STRIPE_W) / 8).max(1) as usize;

    // Reserved HUD chrome in this overlay's logical space; empty on
    // menus where the top-right corner is already clear.
    let reserved: Vec<UiRect> = if state.screen == Screen::InGameHud {
        hud_occupied_rects(state, width, height)
            .iter()
            .map(|r| {
                let x0 = (r.x as f32 / ms as f32).floor() as i32;
                let y0 = (r.y as f32 / ms as f32).floor() as i32;
                let x1 = (r.right() as f32 / ms as f32).ceil() as i32;
                let y1 = (r.bottom() as f32 / ms as f32).ceil() as i32;
                UiRect::new(x0, y0, (x1 - x0).max(0) as u32, (y1 - y0).max(0) as u32)
            })
            .collect()
    } else {
        Vec::new()
    };

    let mut y = EDGE;
    let mut drew = false;
    for toast in state.toasts.visible() {
        let title = hud_str(&toast.title, text_cells);
        let body = hud_str(&toast.body, text_cells);
        let rows = 1 + usize::from(!body.is_empty());
        let line_w = [title.as_str(), body.as_str()]
            .iter()
            .filter(|s| !s.is_empty())
            .map(|s| text_width(s, 1) as i32)
            .max()
            .unwrap_or(0);
        let pw = (line_w + 2 * PAD + STRIPE_W + 2).min(max_w);
        let ph = rows as i32 * ROW_H + 2 * PAD - 1;
        let px = (lw - EDGE - pw).max(EDGE);
        // Slide below whatever HUD chrome the panel would intersect.
        loop {
            let rect = UiRect::new(px, y, pw as u32, ph as u32);
            match reserved.iter().find(|r| rect.intersects(**r)) {
                Some(r) => y = r.bottom() + 2,
                None => break,
            }
            if y + ph > lh - EDGE {
                break;
            }
        }
        if y + ph > lh - EDGE {
            break; // No room for this toast or anything below it.
        }
        let a = toast.alpha();
        let fade = |c: UiColor| c.with_alpha((f32::from(c.a) * a).round() as u8);
        let (ppx, ppy) = (px * ms as i32, y * ms as i32);
        let (ppw, pph) = ((pw * ms as i32) as u32, (ph * ms as i32) as u32);
        out.fill_rect(UiRect::new(ppx, ppy, ppw, pph), fade(pal::PANEL));
        out.border_rect(
            UiRect::new(ppx, ppy, ppw, pph),
            fade(pal::PANEL_BORDER),
            ms,
        );
        let stripe = match toast.kind {
            crate::qol_helpers::ToastKind::Info => pal::TEXT_DIM,
            crate::qol_helpers::ToastKind::Success => pal::ACCENT,
            crate::qol_helpers::ToastKind::Warning => pal::WARNING,
            crate::qol_helpers::ToastKind::Error => pal::DANGER,
        };
        out.fill_rect(
            UiRect::new(ppx, ppy, STRIPE_W as u32 * ms, pph),
            fade(stripe),
        );
        out.text_str(
            (px + STRIPE_W + PAD) * ms as i32,
            (y + PAD) * ms as i32,
            ms,
            fade(pal::TEXT),
            &title,
        );
        if !body.is_empty() {
            out.text_str(
                (px + STRIPE_W + PAD) * ms as i32,
                (y + PAD + ROW_H) * ms as i32,
                ms,
                fade(pal::TEXT_DIM),
                &body,
            );
        }
        y += ph + 4;
        drew = true;
    }
    // "+N more" tail for toasts waiting behind the visible window.
    if drew {
        let pending = state.toasts.pending_count();
        if pending > 0 && y + ROW_H <= lh - EDGE {
            let label = format!("+{pending} more");
            let tw = text_width(&label, 1) as i32;
            out.text_str(
                (lw - EDGE - tw) * ms as i32,
                y * ms as i32,
                ms,
                pal::TEXT_DIM,
                &label,
            );
        }
    }
    drew
}

/// Every rectangle the in-game HUD occupies, in *physical* pixels, for
/// overlays that composite after [`layout_screen`]. Mirrors the `hud()`
/// collision model exactly — same scale, same constants, same clip math —
/// so a later overlay can prove zero overlap against bossbars, MagicHUD,
/// chat, the hotbar stack, and the rest. The MiniHUD box is deliberately
/// absent: it is itself managed against the legacy subtitle stack and
/// anchors to corners the spatial panel only reaches on degenerate
/// layouts.
fn hud_occupied_rects(state: &UiState, width: u32, height: u32) -> Vec<UiRect> {
    let mut rects = Vec::new();
    hud_occupied_rects_into(state, width, height, &mut rects);
    rects
}

/// Fill a reusable buffer with the physical HUD occupancy rectangles.
pub fn hud_occupied_rects_into(state: &UiState, width: u32, height: u32, rects: &mut Vec<UiRect>) {
    rects.clear();
    let hud = &state.hud;
    let qol = &state.settings.qol;
    let s = layout_scale(state, width, height);
    if s <= 0 {
        return;
    }
    let w = (width.min(i32::MAX as u32) as i32) / s;
    let h = (height.min(i32::MAX as u32) as i32) / s;
    if w <= 0 || h <= 0 {
        return;
    }
    let cx = w / 2;

    // Logical-px accumulator; converted to physical at the end.
    {
        let mut add = |x: i32, y: i32, rw: i32, rh: i32| {
            if rw > 0 && rh > 0 {
                rects.push(UiRect::new(x, y, rw as u32, rh as u32));
            }
        };

        // Hotbar block (offhand + gap + 9 slots), vitals columns, XP —
        // the same creative/spectator gates `hud()` applies to the draw.
        let show_vitals = hud.game_mode != 1 && hud.game_mode != 3;
        let show_hotbar = hud.game_mode != 3;
        let slot = 22;
        let hw = 9 * slot;
        let hx = cx - (hw + slot + 4) / 2;
        let hy = h - slot - 4;
        let hotbar_top = hy - 4;
        let hx0 = hx + slot + 4;
        let vy = hy - 12;
        let rx = hx0 + hw;
        // Empty ranges while the rows are gated off — the lift/clip math
        // below then no-ops exactly like the invisible chrome it models.
        let (vl, vr) = if show_vitals {
            (hx0..(hx0 + 80), (rx - 80)..rx)
        } else {
            (0..0, 0..0)
        };
        let vtop_l = vy - if hud.absorption > 0.0 { 20 } else { 10 };
        let vtop_r = vy - if hud.air < 300 { 10 } else { 0 };
        if show_hotbar {
            add(hx, hy, slot + 4 + hw, slot);
        }
        if show_vitals {
            add(cx - 91, hy - 4, 182, 3);
            if hud.xp_level > 0 {
                add(cx - 24, hy - 14, 48, 8);
            }
            add(vl.start, vtop_l, 80, vy + 8 - vtop_l);
            add(vr.start, vtop_r, 80, vy + 8 - vtop_r);
        }

        // Actionbar: centered band directly above the vitals.
        let abar = if hud.actionbar.is_empty() {
            None
        } else {
            let text = hud_str(&hud.actionbar, ((w - 8) / 8).max(0) as usize);
            let aw = text_width(&text, 1) as i32;
            if aw > 0 {
                add(cx - aw / 2, hy - 44, aw, 8);
            }
            Some(cx - aw / 2..cx + aw / 2)
        };
        let abar_band = (hy - 44)..(hy - 36);

        // Legacy directional subtitle rows (same opt-in + same lift
        // math as `hud()`), remembered as `(fill_left, y)` for the chat
        // clip below, plus the stack bottom the conflict button uses.
        let mut subtitle_rows: Vec<(i32, i32)> = Vec::new();
        let mut stack_bottom = hotbar_top;
        if state.settings.qol.show_subtitles && !hud.subtitles.is_empty() {
            let shown: Vec<&HudSubtitle> = hud.subtitles.iter().rev().take(4).collect();
            let build_rows = |base: i32| -> Vec<(String, i32)> {
                shown
                    .iter()
                    .enumerate()
                    .map(|(i, sub)| {
                        let label = match sub.direction {
                            SubtitleDirection::Left => format!("< {}", sub.label),
                            SubtitleDirection::Center => sub.label.clone(),
                            SubtitleDirection::Right => format!("{} >", sub.label),
                            SubtitleDirection::Behind => format!("v {}", sub.label),
                        };
                        let y = base - (shown.len() - i) as i32 * 10;
                        let cells = ((w - 14) / 8).max(1) as usize;
                        (hud_str(&label, cells), y)
                    })
                    .collect()
            };
            let mut sub_base = hotbar_top;
            let mut rows = build_rows(sub_base);
            for (i, (label, y)) in rows.iter().enumerate() {
                let rw = text_width(label, 1) as i32 + 6;
                if w - 4 - rw < vr.end && *y < vy + 8 && *y + 10 > vtop_r {
                    sub_base = sub_base.min(vtop_r - 10 + (shown.len() - i) as i32 * 10);
                }
                if w - 4 - rw < vl.end && *y < vy + 8 && *y + 10 > vtop_l {
                    sub_base = sub_base.min(vtop_l - 10 + (shown.len() - i) as i32 * 10);
                }
            }
            rows = build_rows(sub_base);
            if abar.is_some()
                && rows.iter().any(|(label, y)| {
                    let rw = text_width(label, 1) as i32 + 6;
                    *y < abar_band.end
                        && *y + 10 > abar_band.start
                        && w - 4 - rw < abar.as_ref().map_or(i32::MAX, |ab| ab.end)
                })
            {
                sub_base = (hy - 46).min(sub_base);
                rows = build_rows(sub_base);
            }
            let rows: Vec<(String, i32)> = rows
                .into_iter()
                .filter(|(_, y)| *y >= 0 && *y + 10 <= h)
                .collect();
            for (label, y) in &rows {
                let rw = text_width(label, 1) as i32 + 6;
                add(w - 4 - rw, *y, rw, 10);
            }
            subtitle_rows = rows
                .iter()
                .map(|(label, y)| (w - 4 - (text_width(label, 1) as i32 + 6), *y))
                .collect();
            stack_bottom = sub_base - shown.len() as i32 * 10 - 2;
        }

        // Crafting-conflict switcher (same position math as `hud()`).
        if hud.crafting_conflict.is_active() {
            let label = format!(
                "< {}/{} >",
                hud.crafting_conflict.selected() + 1,
                hud.crafting_conflict.total_candidates
            );
            let bw = (text_width(&label, 1) as i32 + 8).min(w - 8);
            let bx = w - 4 - bw;
            let mut bottom = stack_bottom - 2;
            if bx < vl.end {
                bottom = bottom.min(vtop_l - 2);
            }
            if bx < vr.end {
                bottom = bottom.min(vtop_r - 2);
            }
            let by = (bottom - 14).max(2);
            add(bx, by, bw, 14);
        }

        // Chat scrollback rows, clipped exactly like `hud()` — scroll-
        // lock shifts the window and frees the bottom slot for the
        // unread badge.
        let scroll_locked =
            qol.chat_scroll_lock && state.chat_scroll.scrolled_up;
        let scroll_off = if scroll_locked {
            state.chat_scroll.scroll_offset
        } else {
            0
        };
        let chat_take = if scroll_locked { 5 } else { 6 };
        for (k, line) in hud
            .chat_lines
            .iter()
            .rev()
            .skip(scroll_off)
            .take(chat_take)
            .enumerate()
        {
            let i = k + usize::from(scroll_locked);
            let y = hy - 12 - i as i32 * 10;
            let (band_top, band_bot) = (y - 1, y + 9);
            let mut cells = ((w - 14) / 8).max(0) as usize;
            if band_top < vy + 8 && band_bot > vtop_l {
                cells = cells.min(((vl.start - 10) / 8).max(0) as usize);
            }
            if let Some(ab) = &abar {
                if band_top < abar_band.end && band_bot > abar_band.start {
                    cells = cells.min(((ab.start - 10) / 8).max(0) as usize);
                }
            }
            for (sx, sy) in &subtitle_rows {
                if band_top < *sy + 10 && band_bot > *sy {
                    cells = cells.min(((*sx - 10) / 8).max(0) as usize);
                }
            }
            if cells == 0 {
                continue;
            }
            let text = hud_str(line, cells);
            let tw = text_width(&text, 1) as i32;
            add(2, y - 1, tw + 6, 10);
        }
        // Scroll-lock badge in the freed bottom slot (`hud()` mirror).
        if scroll_locked && hy - 12 >= 0 {
            let badge = state
                .chat_scroll
                .unread_label(state.lang())
                .unwrap_or_else(|| "scrolled".to_string());
            let bw = text_width(&badge, 1) as i32 + 6;
            add(2, hy - 13, bw + 2, 10);
        }

        // Bossbar stack (name text + progress bar per row).
        let boss_count = hud.bossbars.len().min(3) as i32;
        let boss_bottom = if boss_count == 0 {
            4
        } else {
            16 * boss_count + 4
        };
        for (i, (name, _)) in hud.bossbars.iter().take(3).enumerate() {
            let y = 6 + i as i32 * 16;
            let bw = (w - 40).clamp(8, 200);
            let clipped = hud_str(name, ((w - 8) / 8).max(0) as usize);
            let nw = text_width(&clipped, 1) as i32;
            let row_w = bw.max(nw);
            add(cx - row_w / 2, y, row_w, 14);
        }

        // Player-list overlay panel.
        if hud.show_player_list {
            let pw = 200.min(w - 8).max(70);
            let px = cx - pw / 2;
            let py = boss_bottom + 4;
            let rows_avail = ((h - 4 - (py + 14)) / 11).max(0) as usize;
            let (shown, extra) = if hud.players.len() <= rows_avail {
                (hud.players.len(), 0usize)
            } else {
                let s = rows_avail.saturating_sub(1);
                (s, hud.players.len() - s)
            };
            let ph = 14 + (shown + usize::from(extra > 0)) as i32 * 11;
            add(px, py, pw, ph.max(14));
        }

        // MagicHUD bottom bars + top-right status column (same frame the
        // MiniHUD collision code uses).
        if let Some(mf) = magic_frame(&hud.magic, (w * s) as u32, (h * s) as u32, s) {
            add(
                mf.panel.start,
                mf.stack_top,
                mf.panel.end - mf.panel.start,
                h - mf.stack_top,
            );
            add(
                mf.statuses.start,
                0,
                mf.statuses.end - mf.statuses.start,
                mf.status_bottom,
            );
        }
    }

    for rect in rects.iter_mut() {
        *rect = UiRect::new(
            rect.x * s,
            rect.y * s,
            (rect.w as i32 * s).max(0) as u32,
            (rect.h as i32 * s).max(0) as u32,
        );
    }
}

fn slot_cell(ctx: &mut Ctx, x: i32, y: i32, item: Option<&String>, selected: bool) {
    ctx.fill(x, y, 22, 22, pal::SLOT);
    ctx.border(
        x,
        y,
        22,
        22,
        if selected {
            pal::BUTTON_BORDER_HOVER
        } else {
            pal::PANEL_BORDER
        },
    );
    if let Some(name) = item {
        // Two cells max: three glyphs would spill into the next slot.
        ctx.hud_text(x + 3, y + 7, 1, pal::TEXT_DIM, name, 2);
    }
}

/// Vanilla item-cooldown curtain: a translucent wipe covering the top
/// `frac` of the slot's icon area (`frac` = cooldown remaining `0..=1`),
/// with a darker leading edge so the sweep reads as a progress bar.
fn slot_cooldown_wipe(ctx: &mut Ctx, x: i32, y: i32, frac: f32) {
    let frac = frac.clamp(0.0, 1.0);
    if frac <= 0.0 {
        return;
    }
    let cover = ((frac * 20.0).round() as i32).clamp(1, 20);
    ctx.fill(x + 1, y + 1, 20, cover, UiColor::rgba(215, 215, 215, 110));
    ctx.fill(
        x + 1,
        (y + 1 + cover).min(y + 21),
        20,
        1,
        UiColor::rgba(40, 40, 40, 160),
    );
}

/// `count`-icon row of 8px cells (half-unit granularity like vanilla
/// hearts): `value`/`max` in half units.
fn icon_row(ctx: &mut Ctx, x: i32, y: i32, value: f32, max: f32, color: UiColor) {
    let icons = ((max / 2.0).ceil() as i32).clamp(0, 10);
    for i in 0..icons {
        let cx = x + i * 8;
        ctx.fill(cx, y, 8, 8, UiColor::rgb(26, 26, 30));
        let units = (value - i as f32 * 2.0).clamp(0.0, 2.0) / 2.0;
        if units > 0.0 {
            ctx.fill(cx, y, (8.0 * units) as i32, 8, color);
        }
    }
}

/// Right-aligned variant of [`icon_row`].
fn icon_row_r(ctx: &mut Ctx, right: i32, y: i32, value: f32, max: f32, color: UiColor) {
    let icons = ((max / 2.0).ceil() as i32).clamp(0, 10);
    for i in 0..icons {
        let cx = right - 8 - i * 8;
        ctx.fill(cx, y, 8, 8, UiColor::rgb(26, 26, 30));
        let units = (value - i as f32 * 2.0).clamp(0.0, 2.0) / 2.0;
        if units > 0.0 {
            ctx.fill(
                cx + 8 - (8.0 * units) as i32,
                y,
                (8.0 * units) as i32,
                8,
                color,
            );
        }
    }
}

fn ping_bars(ctx: &mut Ctx, x: i32, y: i32, ping_ms: u16) {
    let lit = match ping_ms {
        0..=60 => 5,
        61..=120 => 4,
        161..=300 => 2,
        121..=160 => 3,
        _ => 1,
    };
    for i in 0..5i32 {
        let h = 2 + i;
        let color = if i < lit { pal::ACCENT } else { pal::TEXT_DARK };
        ctx.fill(x + i * 5, y + 8 - h, 3, h, color);
    }
}

// ---------------------------------------------------------------------------
// Pause
// ---------------------------------------------------------------------------

fn pause(ctx: &mut Ctx) {
    ctx.fill(0, 0, ctx.w, ctx.h, pal::OVERLAY_DIM);
    let lang = ctx.lang;
    let cx = ctx.w / 2;

    ctx.ctext(cx, 40, 2, pal::TEXT, tr(lang, "Game Paused", "一時停止中"));

    let bw = 200.min(ctx.w - 8).max(24);
    let x = cx - bw / 2;
    // Seven buttons must clear the Report-Bug corner link at h-26; when
    // the window is too short the stack hugs the top and the link hides.
    let wants_report = !ctx.state.report_url.is_empty();
    let reserve = if wants_report { 28 } else { 2 };
    let step = 24.min((ctx.h - reserve - 20 - 84) / 6).max(4);
    let bh = 20.min(step);
    let mut y = 76.min(ctx.h - reserve - 6 * step - bh).max(2);
    ctx.btn(
        WidgetId::PauseBackToGame,
        lr(x, y, bw, bh),
        tr(lang, "Back to Game", "ゲームに戻る"),
    );
    y += step;
    ctx.btn(
        WidgetId::PauseSettings,
        lr(x, y, bw, bh),
        tr(lang, "Settings", "設定"),
    );
    y += step;
    ctx.btn(
        WidgetId::PauseStatistics,
        lr(x, y, bw, bh),
        tr(lang, "Statistics", "統計"),
    );
    y += step;
    ctx.btn(
        WidgetId::PauseRecipeBrowser,
        lr(x, y, bw, bh),
        tr(lang, "Recipe Browser", "レシピブラウザ"),
    );
    y += step;
    ctx.btn(
        WidgetId::PauseInvite,
        lr(x, y, bw, bh),
        tr(lang, "Invite Friend", "フレンドを招待"),
    );
    y += step;
    ctx.btn(
        WidgetId::PauseSaveReplay,
        lr(x, y, bw, bh),
        tr(lang, "Save 60s Instant Replay", "60sリプレイを保存"),
    );
    y += step;
    ctx.btn(
        WidgetId::PauseSaveQuit,
        lr(x, y, bw, bh),
        tr(lang, "Save & Quit to Title", "保存してタイトルへ"),
    );
    // The corner link draws only when the button stack leaves it room —
    // an overlapping link is worse than a hidden one.
    let stack_bottom = y + bh;
    if wants_report && ctx.h - 26 >= stack_bottom + 2 {
        ctx.btn(
            WidgetId::PauseReportBug,
            lr(ctx.w - 96, ctx.h - 26, 92, 18),
            tr(lang, "Report Bug", "バグ報告"),
        );
    }
}

// ---------------------------------------------------------------------------
// Death & respawn (vanilla DeathScreen)
// ---------------------------------------------------------------------------

fn death(ctx: &mut Ctx) {
    let lang = ctx.lang;
    let cx = ctx.w / 2;
    let state = &ctx.state.death;

    // Vanilla tints the frozen world translucent red under the widgets.
    ctx.fill(0, 0, ctx.w, ctx.h, pal::OVERLAY_DIM);
    ctx.fill(0, 0, ctx.w, ctx.h, UiColor::rgba(140, 0, 0, 80));

    let (title_en, title_ja) = if state.hardcore {
        ("Game over!", "ゲームオーバー")
    } else {
        // ja: the death kanji (死亡) sit outside the built-in atlas, so
        // the hiragana form stands in — vanilla's message minus tofu.
        ("You died!", "しにました")
    };
    let ty = (ctx.h / 4).min(ctx.h.saturating_sub(16)).max(0);
    ctx.ctext(cx, ty, 2, pal::DANGER, tr(lang, title_en, title_ja));

    let mut y = ty + 24;
    if let Some(cause) = state
        .cause_message
        .as_deref()
        .filter(|cause| !cause.is_empty())
    {
        ctx.ctext(cx, y, 1, pal::TEXT, cause);
        y += 12;
    }
    ctx.ctext(
        cx,
        y,
        1,
        pal::TEXT_DIM,
        &format!("{}: {}", tr(lang, "Score", "スコア"), state.score),
    );

    // Buttons below the score line, clamped into the viewport like the
    // pause stack. Hardcore shows vanilla's single centered "Title
    // Screen" — there is no respawn to offer and we implement no
    // spectate mode, so a dead "Spectate World" button would lie.
    let by = (y + 16).min((ctx.h - 22).max(2));
    if state.hardcore {
        let bw = 140.min(ctx.w - 12).max(24);
        ctx.btn(
            WidgetId::DeathTitleScreen,
            lr(cx - bw / 2, by, bw, 20),
            tr(lang, "Title Screen", "タイトル画面へ"),
        );
    } else {
        let bw = 110.min((ctx.w - 12) / 2).max(24);
        ctx.button(
            WidgetId::DeathRespawn,
            lr(cx - bw - 2, by, bw, 20),
            tr(lang, "Respawn", "リスポーン"),
            state.can_respawn(),
        );
        ctx.btn(
            WidgetId::DeathTitleScreen,
            lr(cx + 2, by, bw, 20),
            tr(lang, "Title Screen", "タイトル画面へ"),
        );
    }
}

// ---------------------------------------------------------------------------
// Crash recovery (NotEnoughCrashes-style)
// ---------------------------------------------------------------------------

fn crash(ctx: &mut Ctx) {
    let lang = ctx.lang;
    let cx = ctx.w / 2;

    ctx.fill(0, 0, ctx.w, ctx.h, UiColor::rgb(30, 13, 13));
    ctx.fill(
        0,
        ctx.h / 2,
        ctx.w,
        ctx.h - ctx.h / 2,
        UiColor::rgb(20, 9, 9),
    );

    ctx.ctext(
        cx,
        12,
        2,
        pal::DANGER,
        tr(
            lang,
            "The game crashed - your world is safe",
            "ゲームがクラッシュ — ワールドは安全",
        ),
    );

    let fp = ctx.state.crash_fingerprint();
    ctx.ctext(
        cx,
        40,
        1,
        pal::WARNING,
        &format!("{}: {}", tr(lang, "Crash ID", "クラッシュID"), fp),
    );

    if let Some(c) = &ctx.state.crash {
        let (en, ja) = c.blame_lines();
        // Blame text embeds host data — clip to the viewport, not a
        // fixed pixel width (592px overflows below ~600 logical px).
        let max = ((ctx.w - 16).max(0) as usize).min(74 * 8);
        for (i, line) in [en, ja].iter().enumerate() {
            let clipped = crate::draw::first_px(line, max);
            ctx.ctext(cx, 56 + i as i32 * 10, 1, pal::TEXT_DIM, clipped);
        }
    }

    // Buttons anchor to the viewport bottom; the preview panel shrinks
    // to leave them 8px of clearance.
    let by = (ctx.h - 26).clamp(2, 224);
    let pw = 420.min(ctx.w - 8).max(40);
    let px = cx - pw / 2;
    let preview_h = (by - 8 - 80).clamp(40, 136);
    ctx.panel(px, 80, pw, preview_h);
    let preview = ctx.state.crash_preview();
    let max_px = (pw - 16).max(0) as usize;
    let rows = ((preview_h - 10) / 10).max(0) as usize;
    for (i, line) in preview.lines().take(12.min(rows)).enumerate() {
        let clipped = crate::draw::first_px(line, max_px);
        ctx.text(px + 8, 86 + i as i32 * 10, 1, pal::TEXT_DIM, clipped);
    }

    let sent = ctx.state.crash_sent;
    ctx.button(
        WidgetId::CrashSendReport,
        lr(cx - 140, by, 130, 20),
        tr(
            lang,
            if sent { "Report Sent" } else { "Send Report" },
            if sent {
                "送信済み"
            } else {
                "レポートを送信"
            },
        ),
        !sent && ctx.state.crash.is_some(),
    );
    ctx.btn(
        WidgetId::CrashReturnTitle,
        lr(cx + 10, by, 130, 20),
        tr(lang, "Return to Title", "タイトルへ戻る"),
    );
}

/// Modal overlays; only modal regions are live while open.
fn modal(ctx: &mut Ctx) {
    ctx.fill(0, 0, ctx.w, ctx.h, pal::OVERLAY_DIM);
    let lang = ctx.lang;
    let cx = ctx.w / 2;

    match ctx.state.modal {
        Some(UiModal::ConfirmSendCrashReport) => {
            // The panel shrinks with the viewport instead of spilling.
            let mw = 240.min(ctx.w - 8).max(60);
            let mh = 86.min(ctx.h - 8).max(30);
            let (mx, my) = (cx - mw / 2, (ctx.h / 2 - mh / 2).max(2));
            ctx.panel(mx, my, mw, mh);
            let fp = ctx.state.crash_fingerprint();
            ctx.ctext(
                cx,
                my + 10,
                1,
                pal::TEXT,
                &format!("{} {}", tr(lang, "Send report", "レポートを送信"), fp),
            );
            ctx.ctext(
                cx,
                my + 24,
                1,
                pal::WARNING,
                tr(lang, "Send OK?", "送信してもよい？"),
            );
            // OK + Cancel share the bottom of the modal, split evenly.
            let pair = mw - 22;
            let ok_w = (pair - 6) / 2;
            let cancel_w = pair - 6 - ok_w;
            let ox = mx + (mw - pair) / 2;
            ctx.btn(
                WidgetId::ModalOk,
                lr(ox, my + mh - 34, ok_w, 20),
                tr(lang, "OK", "OK"),
            );
            if let Some(r) = ctx.regions.last_mut() {
                r.modal = true;
            }
            ctx.btn(
                WidgetId::ModalCancel,
                lr(ox + ok_w + 6, my + mh - 34, cancel_w, 20),
                tr(lang, "Cancel", "キャンセル"),
            );
            if let Some(r) = ctx.regions.last_mut() {
                r.modal = true;
            }
        }
        Some(UiModal::ConfirmResetDefaults) => {
            // Reset requires this explicit gate; confirming stays
            // 1-click Undo-recoverable, which the hint says so plainly.
            let mw = 260.min(ctx.w - 8).max(60);
            let mh = 96.min(ctx.h - 8).max(30);
            let (mx, my) = (cx - mw / 2, (ctx.h / 2 - mh / 2).max(2));
            ctx.panel(mx, my, mw, mh);
            ctx.ctext(
                cx,
                my + 10,
                1,
                pal::TEXT,
                tr(lang, "Reset all settings", "すべての設定を"),
            );
            ctx.ctext(
                cx,
                my + 22,
                1,
                pal::TEXT,
                tr(lang, "to defaults?", "初期値に戻す？"),
            );
            ctx.ctext(
                cx,
                my + 36,
                1,
                pal::WARNING,
                tr(lang, "Undo can recover this", "「元に戻す」で復元できます"),
            );
            let pair = mw - 22;
            let ok_w = (pair - 6) / 2;
            let cancel_w = pair - 6 - ok_w;
            let ox = mx + (mw - pair) / 2;
            ctx.btn(
                WidgetId::ModalOk,
                lr(ox, my + mh - 34, ok_w, 20),
                tr(lang, "OK", "OK"),
            );
            if let Some(r) = ctx.regions.last_mut() {
                r.modal = true;
            }
            ctx.btn(
                WidgetId::ModalCancel,
                lr(ox + ok_w + 6, my + mh - 34, cancel_w, 20),
                tr(lang, "Cancel", "キャンセル"),
            );
            if let Some(r) = ctx.regions.last_mut() {
                r.modal = true;
            }
        }
        Some(UiModal::StartupTimeline) => {
            // Per-stage boot telemetry opened from the Boot badge.
            let mw = 340.min(ctx.w - 8).max(80);
            let mh = 190.min(ctx.h - 8).max(40);
            let (mx, my) = (cx - mw / 2, (ctx.h / 2 - mh / 2).max(2));
            ctx.panel(mx, my, mw, mh);
            ctx.ctext(
                cx,
                my + 8,
                1,
                pal::TEXT,
                tr(lang, "Startup Timeline", "起動タイムライン"),
            );
            if let Some(t) = &ctx.state.startup_timeline {
                ctx.ctext(
                    cx,
                    my + 22,
                    1,
                    pal::ACCENT,
                    &format!("{}: {} ms", tr(lang, "Total", "合計"), t.total_ms),
                );
                let rows = ((mh - 84) / 10).max(0) as usize;
                let budget = (mw - 24).max(1) as usize;
                for (i, st) in t.stages.iter().take(rows).enumerate() {
                    let line = format!("{} {}ms {}", st.stage, st.duration_ms, st.detail);
                    ctx.text(
                        mx + 10,
                        my + 36 + i as i32 * 10,
                        1,
                        pal::TEXT_DIM,
                        crate::draw::first_px(&line, budget),
                    );
                }
                ctx.ctext(
                    cx,
                    my + mh - 46,
                    1,
                    pal::TEXT_DIM,
                    &format!(
                        "{}: {} | {}: {} | {}: {}",
                        tr(lang, "native", "ネイティブ"),
                        t.native_mods,
                        "wgpu",
                        t.wgpu_routed_mods,
                        tr(lang, "quarantined", "隔離"),
                        t.quarantined_mods
                    ),
                );
            }
            ctx.btn(
                WidgetId::ModalOk,
                lr(cx - 40, my + mh - 30, 80, 20),
                tr(lang, "OK", "OK"),
            );
            if let Some(r) = ctx.regions.last_mut() {
                r.modal = true;
            }
        }
        None => {}
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::qol_helpers::{KeybindEntry, KeyBindings, ToastKind};

    fn rect_of(cmd: &UiCommand) -> Option<UiRect> {
        match cmd {
            UiCommand::FillRect { rect, .. } | UiCommand::BorderRect { rect, .. } => Some(*rect),
            _ => None,
        }
    }

    #[test]
    fn toast_stack_hidden_when_off_or_empty() {
        let mut state = UiState::default();
        let mut out = UiDrawList::new();
        assert!(!layout_toast_stack(&state, 1280, 720, &mut out));
        assert!(out.commands.is_empty());

        state.push_toast(ToastKind::Info, "hi", "");
        state.settings.qol.toast_notifications = false;
        assert!(!layout_toast_stack(&state, 1280, 720, &mut out));
        assert!(out.commands.is_empty());
    }

    #[test]
    fn toast_stack_draws_top_right_on_menu() {
        let mut state = UiState::default();
        state.push_toast(ToastKind::Success, "Connected", "lobby.example.com");
        // Age the toast past the fade-in so its alpha is 1.
        state.toasts.tick(500);
        let mut out = UiDrawList::new();
        assert!(layout_toast_stack(&state, 1280, 720, &mut out));
        assert!(!out.commands.is_empty());
        // Every emitted rect stays inside the physical viewport and in
        // the right half (right-anchored stack).
        for cmd in &out.commands {
            if let Some(r) = rect_of(cmd) {
                assert!(r.x >= 1280 / 2, "toast leaked left: {r:?}");
                assert!(r.right() <= 1280, "toast overflow: {r:?}");
                assert!(r.bottom() <= 720, "toast overflow: {r:?}");
            }
        }
    }

    #[test]
    fn toast_stack_slides_below_hud_status_column() {
        let mut state = UiState::default();
        state.screen = Screen::InGameHud;
        // MagicHUD status badges anchor the same top-right column the
        // toast stack uses — the toast must slide below them.
        state
            .hud
            .magic
            .custom_statuses
            .push(crate::magic_hud::StatusBadgeState {
                label: "Haste".to_string(),
                remaining_ticks: 100,
                ..Default::default()
            });
        state.push_toast(ToastKind::Info, "tip", "");
        state.toasts.tick(500);
        let mut out = UiDrawList::new();
        assert!(layout_toast_stack(&state, 1280, 720, &mut out));
        // Status badge stack ends ~24 logical px down (≈48 physical at
        // ms=2); the toast panel must start below it.
        let top = out
            .commands
            .iter()
            .filter_map(rect_of)
            .map(|r| r.y)
            .min()
            .unwrap();
        assert!(top >= 40, "toast overlaps HUD statuses: top={top}");
    }

    #[test]
    fn qol_tab_exposes_new_toggle_hit_regions() {
        let mut ui = UiState::default();
        ui.navigate(Screen::Settings(SettingsTab::Qol));
        let (_draw, regions) = layout_screen(&ui, 1280, 720);
        for id in [
            WidgetId::QolAutoReconnect,
            WidgetId::QolChatScrollLock,
            WidgetId::QolToasts,
        ] {
            assert!(
                regions.iter().any(|r| r.id == id),
                "missing hit region for {id:?}"
            );
        }
        // The mod-overlapping helpers stay out of Settings entirely —
        // the community mods in Mods > Recommended do them better.
        for id in [
            WidgetId::QolAutoReplenish,
            WidgetId::QolQuickStack,
            WidgetId::QolFoodPreview,
            WidgetId::QolShulkerPeek,
        ] {
            assert!(
                !regions.iter().any(|r| r.id == id),
                "mod-overlapping toggle {id:?} still rendered"
            );
        }
    }

    #[test]
    fn qol_tab_footer_points_at_mods_recommended() {
        let mut ui = UiState::default();
        ui.navigate(Screen::Settings(SettingsTab::Qol));
        let (draw, _regions) = layout_screen(&ui, 1280, 720);
        let texts: Vec<&str> = draw
            .commands
            .iter()
            .filter_map(|c| match c {
                UiCommand::Text { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect();
        assert!(
            texts
                .iter()
                .any(|t| t.contains("Mods > Recommended")),
            "missing Mods > Recommended footer hint in {texts:?}"
        );
        ui.settings.language = crate::state::LanguageSetting::Japanese;
        let (draw, _regions) = layout_screen(&ui, 1280, 720);
        let texts: Vec<&str> = draw
            .commands
            .iter()
            .filter_map(|c| match c {
                UiCommand::Text { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect();
        let hint = "追加のHUDやインベントリModは Mods > Recommended へ";
        assert!(
            texts.iter().any(|t| t.contains(hint)),
            "missing JA footer hint in {texts:?}"
        );
        for c in hint.chars() {
            assert!(crate::draw::glyph_is_covered(c), "uncovered glyph {c:?}");
        }
    }

    #[test]
    fn qol_tab_shows_recipe_overlay_not_keybind_preview() {
        // Regression: the obsolete Controls/keybind preview painted over
        // the QoL footer. Keybinds live on the dedicated Controls tab
        // now — QoL must render the Recipe Overlay toggle instead.
        let mut ui = UiState::default();
        ui.keybinds = KeyBindings {
            entries: vec![
                KeybindEntry::new("Jump", "Space", false),
                KeybindEntry::new("Boost", "Space", false),
            ],
        };
        ui.navigate(Screen::Settings(SettingsTab::Qol));
        for (w, h) in [(1280u32, 720u32), (640u32, 360u32)] {
            let (draw, regions) = layout_screen(&ui, w, h);
            assert!(
                regions.iter().any(|r| r.id == WidgetId::QolRecipeOverlay),
                "Recipe Overlay toggle missing at {w}x{h}"
            );
            let texts: Vec<&str> = draw
                .commands
                .iter()
                .filter_map(|c| match c {
                    UiCommand::Text { text, .. } => Some(text.as_str()),
                    _ => None,
                })
                .collect();
            for needle in ["[!]", "conflict", "重複", "Forward:", "前進:"] {
                assert!(
                    !texts.iter().any(|t| t.contains(needle)),
                    "obsolete keybind preview text {needle:?} still rendered \
                     on QoL at {w}x{h}: {texts:?}"
                );
            }
        }
    }

    #[test]
    fn hud_scroll_lock_shows_unread_badge() {
        let mut state = UiState::default();
        state.screen = Screen::InGameHud;
        for i in 0..12 {
            state.hud.chat_lines.push(format!("line{i}"));
        }
        state.chat_scroll.scroll_by(4);
        for _ in 0..3 {
            state.chat_scroll.on_new_message();
        }
        let (draw, _) = layout_screen(&state, 1280, 720);
        assert!(draw.commands.iter().any(|c| matches!(
            c,
            UiCommand::Text { text, color, .. }
                if text.contains("+") && *color == pal::WARNING
        )));
    }

    // -------------------------------------------------------------------
    // Player-facing guards: settings tab ownership, anti-dev-jargon copy,
    // Japanese completeness, and zero-tofu glyph coverage. These pin the
    // regressions where video controls leaked onto the Controls tab,
    // English labels fell through in Japanese, and internal jargon shipped.
    // -------------------------------------------------------------------

    /// Every menu screen a player can reach without live session data.
    /// Embedded sub-screens (`ModMenu`, `RecipeBrowser`) and the in-game
    /// HUD render their own trees with dedicated test modules — this
    /// list covers the native chrome and tab chrome.
    fn menu_screens() -> Vec<(String, Screen)> {
        let mut out: Vec<(String, Screen)> = [
            Screen::Title,
            Screen::Singleplayer,
            Screen::Multiplayer,
            Screen::AboutMegu,
            Screen::Friends,
            Screen::ModSyncConsent,
            Screen::ModSyncPrompt,
            Screen::Disconnected,
            Screen::Pause,
            Screen::Death,
            Screen::CrashRecovery,
        ]
        .into_iter()
        .map(|s| (format!("{s:?}"), s))
        .collect();
        for tab in SettingsTab::ALL {
            out.push((format!("Settings({tab:?})"), Screen::Settings(tab)));
        }
        out
    }

    /// State that exercises the *UI chrome*: every link row is populated,
    /// while host-provided data (rebind action names are real English
    /// identifiers the host ships regardless of locale) is emptied so the
    /// guards pin layout strings, not host data.
    fn menu_state(lang: UiLang, screen: Screen) -> UiState {
        let mut ui = UiState::default();
        if lang == UiLang::Ja {
            // The same code path the host takes on a locale pick: sets
            // both `settings.language` (tr) and `settings.locale`
            // (ui_text / i18n catalog).
            ui.set_locale(megu_core::i18n::BuiltinLocale::JaJp);
        }
        ui.keybinds = KeyBindings::default();
        ui.website_url = "https://megu.megumin.tech/".to_string();
        ui.support_url = "https://megu.megumin.tech/#support".to_string();
        ui.contribute_url = "https://github.com/nekomario28/megu-mc".to_string();
        ui.report_url = "https://megu.megumin.tech/#report".to_string();
        ui.navigate(screen);
        ui
    }

    fn rendered_texts(state: &UiState, w: u32, h: u32) -> Vec<String> {
        let (draw, _) = layout_screen(state, w, h);
        draw.commands
            .iter()
            .filter_map(|c| match c {
                UiCommand::Text { text, .. } => Some(text.clone()),
                _ => None,
            })
            .collect()
    }

    #[test]
    fn settings_tabs_own_their_widget_ids() {
        for (w, h) in [(1280u32, 720u32), (640u32, 360u32)] {
            // Render all seven tabs once each; bucket every hit region by
            // the tab that emitted it.
            let mut hits: Vec<(SettingsTab, WidgetId)> = Vec::new();
            for tab in SettingsTab::ALL {
                let ui = menu_state(UiLang::En, Screen::Settings(tab));
                let (_, regions) = layout_screen(&ui, w, h);
                hits.extend(regions.iter().map(|r| (tab, r.id)));
            }
            let tabs_of = |pred: &dyn Fn(WidgetId) -> bool| -> Vec<SettingsTab> {
                let mut seen: Vec<SettingsTab> = hits
                    .iter()
                    .filter(|(_, id)| pred(*id))
                    .map(|(tab, _)| *tab)
                    .collect();
                seen.dedup();
                seen
            };
            // Video widgets belong to Video alone — the regression that
            // painted them on Controls.
            for id in [
                WidgetId::VideoFullscreen,
                WidgetId::VideoGamma,
                WidgetId::VideoGuiScale,
                WidgetId::VideoEntityShadows,
                WidgetId::VideoClouds,
            ] {
                assert_eq!(
                    tabs_of(&|i| i == id),
                    [SettingsTab::Video],
                    "{id:?} must render only on Video at {w}x{h}"
                );
            }
            // The relocated built-ins and MiniHUD chips are QoL-only.
            assert_eq!(
                tabs_of(&|i| matches!(i, WidgetId::QolBuiltin(_))),
                [SettingsTab::Qol],
                "QolBuiltin leaked off the QoL tab at {w}x{h}"
            );
            assert_eq!(
                tabs_of(&|i| matches!(i, WidgetId::MiniHudSegment(_))),
                [] as [SettingsTab; 0],
                "MiniHudSegment rendered with MiniHUD off at {w}x{h}"
            );
            // Rebind cells and the mouse-Y toggle are Controls-only.
            assert_eq!(
                tabs_of(&|i| matches!(i, WidgetId::ControlKey(_))),
                [SettingsTab::Controls],
                "ControlKey leaked off the Controls tab at {w}x{h}"
            );
            assert_eq!(
                tabs_of(&|i| i == WidgetId::VideoInvertY),
                [SettingsTab::Controls],
                "VideoInvertY must render only on Controls at {w}x{h}"
            );
            // Positive anchors: the ids do appear on their owning tab.
            for id in [
                WidgetId::VideoFullscreen,
                WidgetId::VideoGamma,
                WidgetId::VideoGuiScale,
                WidgetId::VideoEntityShadows,
                WidgetId::VideoClouds,
            ] {
                assert!(
                    hits.iter().any(|(t, i)| *t == SettingsTab::Video && *i == id),
                    "{id:?} missing from Video at {w}x{h}"
                );
            }
            // With MiniHUD on, its chips still belong to QoL alone.
            let mut ui = menu_state(UiLang::En, Screen::Settings(SettingsTab::Qol));
            ui.settings.qol.mini_hud.enabled = true;
            let (_, regions) = layout_screen(&ui, w, h);
            assert!(
                regions
                    .iter()
                    .any(|r| matches!(r.id, WidgetId::MiniHudSegment(_))),
                "MiniHudSegment missing on QoL with MiniHUD on at {w}x{h}"
            );
        }
        // The chips never render outside QoL even when enabled.
        for tab in SettingsTab::ALL {
            let mut ui = menu_state(UiLang::En, Screen::Settings(tab));
            ui.settings.qol.mini_hud.enabled = true;
            let (_, regions) = layout_screen(&ui, 1280, 720);
            if tab == SettingsTab::Qol {
                continue;
            }
            assert!(
                !regions
                    .iter()
                    .any(|r| matches!(r.id, WidgetId::MiniHudSegment(_))),
                "MiniHudSegment leaked onto {tab:?}"
            );
        }
    }

    #[test]
    fn player_facing_screens_carry_no_dev_jargon() {
        // Internal codenames, license spdx, and dev-notes phrasing that
        // must never reach a player-facing string.
        const JARGON: &[&str] = &[
            "Protocol 767",
            "zero-dep",
            "client-ui",
            "Zsh command",
            "GPL-3.0-or-later",
            "AGPL-3.0-or-later",
            "clean-room",
            "(opt-in)",
        ];
        // Token check: jargon must not appear as a standalone token, but
        // LGPL-3.0-or-later (the real license) contains no bare GPL/AGPL.
        fn has_token(text: &str, needle: &str) -> bool {
            text.match_indices(needle).any(|(i, _)| {
                text[..i]
                    .chars()
                    .next_back()
                    .is_none_or(|c| !c.is_ascii_alphanumeric() && c != '-')
            })
        }
        for lang in [UiLang::En, UiLang::Ja] {
            for (name, screen) in menu_screens() {
                for (w, h) in [(1280u32, 720u32), (640u32, 360u32)] {
                    let ui = menu_state(lang, screen);
                    for text in rendered_texts(&ui, w, h) {
                        for jargon in JARGON {
                            assert!(
                                !has_token(&text, jargon),
                                "{name} ({lang:?} {w}x{h}) renders dev jargon \
                                 {jargon:?} in {text:?}"
                            );
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn ja_menu_labels_never_fall_back_to_english() {
        // English phrases a Japanese build shipped before they were
        // translated — the exact regression fingerprints.
        const KNOWN_LEAKS: &[&str] = &[
            "Master Volume",
            "Hostile Mobs",
            "Friendly Mobs",
            "Same-Sound",
            "Forward",
            "Swap Offhand",
            "Advancements",
            "Sort Inventory",
            "Fullscreen:",
            "Brightness:",
            "GUI Scale:",
            "Invert Y:",
            "Looking-at HUD",
            "Mouse tweaks",
            "Inventory sort",
            "Press any key",
        ];
        // Latin tokens that are legitimate on Japanese screens (brand,
        // units, feature names, and the few real English proper nouns).
        const ALLOWED_LATIN: &[&str] = &[
            "MINECRAFT", "MEGU", "EDITION", "ENHANCED", "Megu", "Minecraft",
            "Mod", "Mods", "Modrinth", "Recommended", "VSync", "FPS", "TPS",
            "MSPT", "BGM", "RAM", "GPU", "LOD", "GUI", "HUD", "LAN", "ID",
            "OK", "SHA", "ON", "OFF", "E2EE", "LGPL", "QoL", "later", "ms",
            "fps", "id", "v", "tick", "MiB", "GiB", "KiB", "c", "dB",
            // Locale autonyms render natively regardless of UI language.
            "English", "Deutsch", "Fran", "Espa", "Italiano", "Polski",
            "json",
            // Short key-name forms emitted by `format_key_label`.
            "Ctrl", "Super", "Esc", "BS", "Caps", "Ins", "Del", "Pg",
            "Enter", "LMB", "RMB", "MMB",
        ];
        let mut screens = vec![
            ("Title".to_string(), Screen::Title),
            ("AboutMegu".to_string(), Screen::AboutMegu),
            ("Pause".to_string(), Screen::Pause),
            ("ModSyncPrompt".to_string(), Screen::ModSyncPrompt),
        ];
        screens.extend(
            SettingsTab::ALL
                .into_iter()
                .map(|tab| (format!("Settings({tab:?})"), Screen::Settings(tab))),
        );
        for (name, screen) in screens {
            for (w, h) in [(1280u32, 720u32), (640u32, 360u32)] {
                let ui = menu_state(UiLang::Ja, screen);
                for text in rendered_texts(&ui, w, h) {
                    for leak in KNOWN_LEAKS {
                        assert!(
                            !text.contains(leak),
                            "{name} {w}x{h} JA label fell back to {leak:?} in {text:?}"
                        );
                    }
                    // Generic fallback catch: no run of Latin letters
                    // (a whole untranslated word) outside the allowlist.
                    // SDL-style bound-key names (`KeyW`, `ShiftLeft`,
                    // `F11`, `Space`) are host data, not chrome.
                    fn key_name(word: &str) -> bool {
                        word.starts_with("Key")
                            || word.starts_with("Mouse")
                            || word.starts_with("Arrow")
                            || word.starts_with("Num")
                            || word.starts_with("Shift")
                            || word.starts_with("Control")
                            || word.starts_with("Alt")
                            || word.starts_with("Page")
                            || word.starts_with("F")
                                && word[1..].chars().all(|c| c.is_ascii_digit())
                            || matches!(
                                word,
                                "Space"
                                    | "Slash"
                                    | "Tab"
                                    | "Backspace"
                                    | "CapsLock"
                                    | "Return"
                                    | "Escape"
                                    | "Grave"
                                    | "Minus"
                                    | "Equal"
                                    | "Comma"
                                    | "Period"
                                    | "Semicolon"
                                    | "Apostrophe"
                                    | "Backslash"
                                    | "Delete"
                                    | "Insert"
                                    | "Home"
                                    | "End"
                            )
                    }
                    for word in text
                        .split(|c: char| !c.is_ascii_alphabetic())
                        .filter(|s| s.len() >= 3 && !key_name(s))
                    {
                        assert!(
                            ALLOWED_LATIN
                                .iter()
                                .any(|allowed| word.contains(allowed) || allowed.contains(word)),
                            "{name} {w}x{h} JA label has untranslated word \
                             {word:?} in {text:?}"
                        );
                    }
                }
            }
        }
        // While a rebinding capture is armed the Controls tab prompts in
        // Japanese, never in English.
        let mut ui = menu_state(UiLang::Ja, Screen::Settings(SettingsTab::Controls));
        ui.capturing_key_binding = Some(0);
        let texts = rendered_texts(&ui, 1280, 720);
        assert!(
            texts.iter().any(|t| t.contains("キーを押してください")),
            "Controls capture prompt is not Japanese: {texts:?}"
        );
        assert!(
            !texts.iter().any(|t| t.contains("Press any key")),
            "Controls capture prompt leaked English: {texts:?}"
        );
    }

    #[test]
    fn every_ja_screen_has_zero_tofu_glyphs() {
        use std::collections::BTreeSet;
        let mut uncovered: BTreeSet<char> = BTreeSet::new();
        let mut offenders: Vec<String> = Vec::new();
        for (name, screen) in menu_screens() {
            for (w, h) in [(1280u32, 720u32), (640u32, 360u32)] {
                let ui = menu_state(UiLang::Ja, screen);
                for text in rendered_texts(&ui, w, h) {
                    if text
                        .chars()
                        .any(|c| !crate::draw::glyph_is_covered(c))
                    {
                        uncovered.extend(
                            text.chars()
                                .filter(|c| !crate::draw::glyph_is_covered(*c)),
                        );
                        offenders.push(format!("{name} {w}x{h}: {text:?}"));
                    }
                }
            }
        }
        assert!(
            uncovered.is_empty(),
            "JA tofu glyphs: {:?} (U+{:04X?}) — offenders: {:?}",
            uncovered,
            uncovered.iter().map(|c| *c as u32).collect::<Vec<_>>(),
            offenders
        );
    }
}

